-- Generated by scripts/catalogue-v2-seed.py from docs/fitness/approved/catalogue-v2/*.json
-- 224 exercises. Re-run the script instead of editing by hand.
insert into public.exercises (id, name_en, name_es, body_region, primary_muscle, primary_muscles,
  secondary_muscles, equipment, movement_pattern, mechanic, laterality, posture_tips, aliases, is_active) values
  ('ab-wheel-rollout', 'Ab Wheel Rollout', 'Rueda abdominal', 'Core', 'Abs', array['Abs']::text[], array['Lats', 'Obliques', 'Hip Flexors']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Arrodíllate sobre una colchoneta y sujeta la rueda bajo los hombros con los brazos rectos.', 'Mantén la pelvis metida y las costillas abajo durante todo el recorrido.', 'Rueda hacia delante hasta donde controles y vuelve tirando con el abdomen.', 'Evita que la zona lumbar se hunda al alejarte de las rodillas.', 'Aumenta la distancia de forma progresiva; empieza con recorridos cortos.']::text[], '{}'::text[], true),
  ('back-extension-single-leg', 'Back Extension (Single-Leg)', 'Hiperextensión (a una pierna)', 'Glutes', 'Glutes', array['Glutes', 'Hamstrings']::text[], array['Lower Back']::text[], 'bodyweight', 'hinge', 'compound', 'unilateral', array['Colócate en el banco de 45° con un solo pie fijado y la otra pierna suelta detrás.', 'Mantén la pelvis nivelada sin dejar que la cadera libre caiga o rote.', 'Desciende flexionando la cadera de apoyo y sube contrayendo el glúteo de esa pierna.', 'Evita girar el tronco para compensar la falta de fuerza de un lado.', 'Domina primero la versión a dos piernas antes de pasar a esta.']::text[], '{}'::text[], true),
  ('back-squat', 'Barbell Back Squat', 'Sentadilla trasera con barra', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors', 'Lower Back']::text[], 'barbell', 'squat', 'compound', 'bilateral', array['Apoya la barra sobre los trapecios, pies al ancho de hombros y puntas un poco hacia afuera.', 'Mantén el pecho alto y la espalda neutra, con las rodillas siguiendo la dirección de los pies.', 'Baja controlando hasta al menos paralelo y sube empujando el suelo con todo el pie.', 'Evita que las rodillas se cierren hacia dentro al subir desde el fondo.', 'Entrena dentro de un rack con los seguros ajustados justo debajo de tu profundidad.']::text[], '{}'::text[], true),
  ('band-assisted-pull-up', 'Band Assisted Pull-Up', 'Dominadas asistidas con banda', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'band', 'pull vertical', 'compound', 'bilateral', array['Ata la banda a la barra y coloca una rodilla o un pie dentro antes de colgarte con agarre prono.', 'Mantén el cuerpo en línea y el abdomen firme para que la banda no te balancee.', 'Tira hasta la barbilla sobre la barra y baja controlando, sin dejar que la banda te dispare hacia arriba.', 'Evita depender de una banda muy gruesa; cambia a una más fina cuando completes tus repeticiones.', 'Revisa que la banda no tenga cortes y que esté bien anudada antes de cada serie.']::text[], '{}'::text[], true),
  ('band-lateral-walk', 'Band Lateral Walk', 'Caminata lateral con banda', 'Glutes', 'Abductors', array['Abductors', 'Glutes']::text[], '{}'::text[], 'band', 'isolation', 'isolation', 'bilateral', array['Coloca una banda elástica sobre las rodillas o los tobillos y flexiona un poco cadera y rodillas.', 'Mantén la tensión de la banda y la postura semiflexionada en todos los pasos.', 'Da pasos laterales cortos y controlados sin juntar los pies del todo.', 'Evita balancear el tronco de lado a lado al dar cada paso.', 'Revisa que la banda no esté agrietada antes de usarla.']::text[], '{}'::text[], true),
  ('band-pull-apart', 'Band Pull-Apart', 'Separaciones con banda elástica', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back']::text[], 'band', 'isolation', 'isolation', 'bilateral', array['Sujeta la banda frente al pecho con los brazos extendidos y las manos a la anchura de los hombros.', 'Mantén las costillas abajo y los hombros lejos de las orejas.', 'Separa las manos llevando la banda hacia el pecho y vuelve sin perder tensión.', 'No dobles los codos para facilitar el movimiento.', 'Revisa la banda antes de usarla y descártala si tiene grietas o cortes.']::text[], '{}'::text[], true),
  ('band-straight-arm-pulldown', 'Band Straight-Arm Pulldown', 'Jalón con brazos rectos con banda', 'Back', 'Lats', array['Lats']::text[], array['Triceps', 'Rear Delts']::text[], 'band', 'isolation', 'isolation', 'bilateral', array['Ancla la banda por encima de la cabeza, agárrala con ambas manos y aléjate hasta notar tensión.', 'Mantén los brazos estirados, el pecho alto y una leve bisagra de cadera.', 'Baja las manos en arco hasta las caderas y vuelve lento hasta la altura de los hombros.', 'Evita encoger los hombros cuando la banda tira hacia arriba al volver.', 'Revisa el anclaje y el estado de la banda; si se suelta puede golpearte.']::text[], '{}'::text[], true),
  ('barbell-bench-press', 'Barbell Bench Press', 'Press de banca con barra', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Túmbate con los ojos bajo la barra, pies firmes en el suelo y agarre algo más ancho que los hombros.', 'Junta las escápulas y mantén un ligero arco lumbar con glúteos y cabeza apoyados en el banco.', 'Baja la barra controlada hasta la parte baja del pecho y empuja hacia arriba y un poco hacia atrás.', 'Evita abrir los codos a 90°; mantenlos a unos 45-70° del torso al bajar.', 'Usa topes de seguridad o un compañero de spotting cuando trabajes cerca del fallo.']::text[], array['bb-bench-press']::text[], true),
  ('barbell-bent-over-row', 'Barbell Bent-Over Row', 'Remo inclinado con barra', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps', 'Lower Back']::text[], 'barbell', 'pull horizontal', 'compound', 'bilateral', array['Coge la barra en prono algo más ancho que los hombros e inclina el torso a unos 45° con rodillas flexionadas.', 'Mantén la espalda neutra y el cuello alineado, mirando al suelo un poco por delante de ti.', 'Lleva la barra hacia el ombligo juntando las escápulas y bájala hasta extender los brazos sin moverte.', 'Evita incorporar el torso en cada repetición para subir la barra con impulso.', 'Si no puedes mantener la espalda neutra, reduce la carga antes de seguir.']::text[], '{}'::text[], true),
  ('barbell-box-squat', 'Barbell Box Squat', 'Sentadilla a cajón con barra', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Hamstrings', 'Adductors', 'Lower Back']::text[], 'barbell', 'squat', 'compound', 'bilateral', array['Coloca un cajón detrás a la altura de paralelo y adopta una postura algo más ancha de lo normal.', 'Lleva la cadera atrás manteniendo las tibias casi verticales y el pecho arriba.', 'Siéntate suavemente en el cajón, pausa un instante sin relajarte y sube con fuerza.', 'Evita dejarte caer sobre el cajón ni balancearte hacia atrás para impulsarte.', 'Comprueba que el cajón sea estable y no se deslice antes de empezar.']::text[], '{}'::text[], true),
  ('barbell-curl', 'Barbell Curl', 'Curl con barra', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'barbell', 'isolation', 'isolation', 'bilateral', array['Sujeta la barra con agarre supino a la anchura de los hombros y los brazos extendidos.', 'Mantén los glúteos y el abdomen activos para que el tronco no se arquee hacia atrás.', 'Sube la barra en arco hasta el pecho sin mover los codos y baja en 2-3 segundos.', 'Evita dar un golpe de cadera para arrancar la barra desde abajo.', 'Si notas tirantez en las muñecas con la barra recta, usa una barra Z.']::text[], '{}'::text[], true),
  ('barbell-deadlift', 'Barbell Deadlift', 'Peso muerto con barra', 'Legs', 'Glutes', array['Glutes', 'Hamstrings']::text[], array['Lower Back', 'Quads', 'Traps', 'Forearms']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Coloca los pies al ancho de cadera con la barra sobre el centro del pie y agárrala por fuera de las piernas.', 'Mantén la espalda neutra y la barra pegada al cuerpo durante todo el ascenso.', 'Empuja el suelo con las piernas, extiende la cadera arriba y baja deslizando la barra por los muslos.', 'Evita que la cadera suba antes que la barra y redondee la espalda.', 'Tensa el abdomen antes de cada repetición y deja la barra en el suelo en cada rep si pierdes la postura.']::text[], '{}'::text[], true),
  ('barbell-deadlift-sumo', 'Barbell Deadlift (Sumo)', 'Peso muerto con barra (sumo)', 'Legs', 'Glutes', array['Glutes', 'Adductors']::text[], array['Quads', 'Hamstrings', 'Lower Back']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Abre los pies bien por fuera de los hombros, puntas hacia afuera y agarra la barra entre las piernas.', 'Mantén el pecho alto y empuja las rodillas hacia afuera sobre las puntas de los pies.', 'Separa la barra del suelo empujando con las piernas y termina juntando la cadera con la barra.', 'Evita que las rodillas se cierren hacia dentro al despegar la barra.', 'Calienta los aductores con series ligeras antes de cargar la barra.']::text[], '{}'::text[], true),
  ('barbell-front-squat', 'Barbell Front Squat', 'Sentadilla frontal con barra', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Upper Back', 'Abs']::text[], 'barbell', 'squat', 'compound', 'bilateral', array['Apoya la barra sobre los deltoides frontales con los codos altos, en agarre limpio o cruzado.', 'Mantén los codos arriba y el torso vertical durante toda la bajada.', 'Baja entre las piernas hasta romper el paralelo y sube guiando con los codos.', 'Evita que los codos caigan, porque la barra rodará hacia delante.', 'Si pierdes la barra, suéltala hacia delante y aléjate; usa los seguros del rack.']::text[], '{}'::text[], true),
  ('barbell-glute-bridge', 'Barbell Glute Bridge', 'Puente de glúteo con barra', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Túmbate en el suelo con la barra acolchada sobre la cadera y los pies cerca de los glúteos.', 'Mantén la espalda alta apoyada y las rodillas separadas al ancho de cadera.', 'Eleva la cadera hasta la extensión, mantén un segundo y baja hasta rozar el suelo.', 'Evita separar los talones del suelo al subir.', 'Usa discos grandes para poder rodar la barra sobre las piernas al colocarte.']::text[], '{}'::text[], true),
  ('barbell-good-morning', 'Barbell Good Morning', 'Buenos días con barra', 'Legs', 'Hamstrings', array['Hamstrings', 'Lower Back']::text[], array['Glutes']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Apoya la barra sobre los trapecios como en la sentadilla, con los pies al ancho de cadera.', 'Mantén la espalda neutra y las rodillas ligeramente flexionadas durante la bisagra.', 'Lleva la cadera atrás inclinando el tronco hasta casi paralelo y sube apretando glúteos.', 'Evita bajar el pecho redondeando la espalda en lugar de mover la cadera.', 'Empieza con cargas ligeras y hazlo dentro del rack con los seguros puestos.']::text[], '{}'::text[], true),
  ('barbell-hip-thrust', 'Barbell Hip Thrust', 'Hip thrust con barra', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings', 'Quads']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Apoya la parte baja de las escápulas en un banco y coloca la barra acolchada sobre la cadera.', 'Mantén la barbilla recogida y las costillas abajo durante la subida.', 'Empuja con los talones hasta alinear rodillas, cadera y hombros, pausa y baja controlado.', 'Evita terminar arqueando la zona lumbar en vez de extender la cadera.', 'Usa una almohadilla en la barra y un banco fijo que no se deslice.']::text[], '{}'::text[], true),
  ('barbell-jm-press', 'Barbell JM Press', 'Press JM con barra', 'Arms', 'Triceps', array['Triceps']::text[], array['Chest', 'Front Delts']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Túmbate en un banco plano con agarre cerrado, algo más estrecho que los hombros.', 'Mantén los codos apuntando hacia los pies y los omóplatos apoyados en el banco.', 'Baja la barra hacia la parte alta del pecho o barbilla flexionando los codos y empuja hacia arriba.', 'Evita convertirlo en un press de banca: la barra no debe tocar el pecho.', 'Usa soportes de seguridad o un compañero; la barra baja cerca de la cara.']::text[], '{}'::text[], true),
  ('barbell-lunge-reverse', 'Barbell Lunge (Reverse)', 'Zancada con barra (hacia atrás)', 'Legs', 'Glutes', array['Glutes', 'Quads']::text[], array['Hamstrings', 'Adductors', 'Abs']::text[], 'barbell', 'lunge', 'compound', 'unilateral', array['Saca la barra del rack sobre los trapecios y da dos pasos atrás para tener espacio.', 'Mantén el abdomen firme y la barra quieta, sin inclinarla hacia un lado.', 'Retrocede un paso, baja vertical y regresa empujando con el pie delantero.', 'Evita ir con prisa; cada repetición debe empezar con los pies juntos y estables.', 'Trabaja dentro del rack con los seguros puestos por si pierdes el equilibrio.']::text[], '{}'::text[], true),
  ('barbell-meadows-row', 'Barbell Meadows Row', 'Remo Meadows con barra', 'Back', 'Lats', array['Lats', 'Upper Back']::text[], array['Rear Delts', 'Biceps', 'Forearms']::text[], 'barbell', 'pull horizontal', 'compound', 'unilateral', array['Colócate perpendicular a la barra anclada, agarra el extremo en prono y apoya el antebrazo libre en la rodilla.', 'Mantén la cadera alta, el torso inclinado y la espalda neutra sin rotar.', 'Tira del extremo de la barra hacia la cadera con el codo abierto y baja hasta estirar el dorsal.', 'Evita girar el torso hacia arriba para mover la carga; el giro debe ser mínimo.', 'Usa discos pequeños para tener más recorrido y ancla bien la barra antes de empezar.']::text[], '{}'::text[], true),
  ('barbell-overhead-press', 'Barbell Overhead Press (Standing)', 'Press militar con barra (de pie)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps', 'Upper Chest', 'Abs']::text[], 'barbell', 'push vertical', 'compound', 'bilateral', array['Saca la barra del rack a la altura de las clavículas, con agarre algo más ancho que los hombros.', 'Aprieta glúteos y abdomen para mantener las costillas abajo y la espalda neutra.', 'Empuja la barra en línea recta, mete la cabeza bajo ella arriba y baja a las clavículas.', 'Evita inclinarte hacia atrás para convertirlo en un press inclinado.', 'Coloca los soportes del rack a la altura del pecho para sacar y devolver la barra con seguridad.']::text[], '{}'::text[], true),
  ('barbell-overhead-press-seated', 'Barbell Overhead Press (Seated)', 'Press militar con barra (sentado)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'barbell', 'push vertical', 'compound', 'bilateral', array['Siéntate en un banco con respaldo vertical bajo la barra del rack, con los pies firmes.', 'Mantén la espalda contra el respaldo y la cabeza neutra.', 'Baja la barra por delante de la cara hasta la barbilla y empuja hasta extender los brazos.', 'No bajes la barra por detrás de la nuca.', 'Ajusta los soportes para poder desenganchar la barra sin estirar los brazos al límite.']::text[], '{}'::text[], true),
  ('barbell-pendlay-row', 'Barbell Pendlay Row', 'Remo Pendlay con barra', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps', 'Lower Back']::text[], 'barbell', 'pull horizontal', 'compound', 'bilateral', array['Colócate con la barra en el suelo sobre la mitad del pie y el torso casi paralelo al suelo.', 'Mantén la espalda plana y la cadera alta, sin cambiar el ángulo del torso entre repeticiones.', 'Tira la barra explosivamente al abdomen y devuélvela al suelo en cada repetición, parando por completo.', 'Evita levantar el torso para ayudarte; si lo haces, la carga es demasiado alta.', 'Deja la barra en el suelo con control en lugar de soltarla para proteger la espalda y el equipo.']::text[], '{}'::text[], true),
  ('barbell-power-clean', 'Barbell Power Clean', 'Cargada de potencia con barra', 'Full Body', 'Glutes', array['Glutes', 'Quads']::text[], array['Hamstrings', 'Traps', 'Upper Back', 'Lower Back']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Colócate con la barra sobre el empeine, pies al ancho de la cadera y agarre algo más ancho.', 'Mantén la espalda neutra y la barra pegada al cuerpo durante todo el tirón.', 'Extiende cadera y rodillas con fuerza y recibe la barra sobre los hombros con los codos al frente.', 'Evita tirar con los brazos antes de extender por completo la cadera.', 'Aprende la técnica con poco peso o un entrenador y usa discos que puedan caer al suelo.']::text[], '{}'::text[], true),
  ('barbell-reverse-curl', 'Barbell Reverse Curl', 'Curl inverso con barra', 'Arms', 'Forearms', array['Forearms', 'Biceps']::text[], '{}'::text[], 'barbell', 'isolation', 'isolation', 'bilateral', array['Sujeta la barra con agarre prono a la anchura de los hombros y los brazos extendidos.', 'Mantén las muñecas rectas, alineadas con el antebrazo, durante todo el recorrido.', 'Sube la barra flexionando los codos hasta el pecho y bájala lentamente.', 'Evita doblar las muñecas hacia abajo cuando aparece la fatiga.', 'Usa menos peso que en el curl normal; el agarre prono limita la carga segura.']::text[], '{}'::text[], true),
  ('barbell-reverse-wrist-curl', 'Barbell Reverse Wrist Curl', 'Curl de muñeca inverso con barra', 'Arms', 'Forearms', array['Forearms']::text[], '{}'::text[], 'barbell', 'isolation', 'isolation', 'bilateral', array['Apoya los antebrazos en los muslos o el banco con las palmas hacia abajo y las muñecas fuera.', 'Mantén los antebrazos pegados al apoyo y los dedos firmes alrededor de la barra.', 'Eleva el dorso de las manos todo lo posible y baja lentamente hasta el estiramiento.', 'Evita mover los codos o balancear la barra para ganar recorrido.', 'Empieza con muy poco peso: los extensores del antebrazo se fatigan rápido.']::text[], '{}'::text[], true),
  ('barbell-seal-row', 'Barbell Seal Row', 'Remo foca con barra', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps']::text[], 'barbell', 'pull horizontal', 'compound', 'bilateral', array['Túmbate boca abajo en un banco alto y plano con la barra debajo y los brazos colgando estirados.', 'Mantén el pecho y la cadera pegados al banco y la cabeza en línea con el torso.', 'Tira la barra hasta tocar la parte inferior del banco y bájala despacio hasta extender los brazos.', 'Evita levantar el pecho del banco para ganar recorrido; pierdes el apoyo y la tensión.', 'Asegúrate de que el banco esté estable sobre cajones o soportes antes de tumbarte.']::text[], '{}'::text[], true),
  ('barbell-shrug', 'Barbell Shrug', 'Encogimientos con barra', 'Back', 'Traps', array['Traps']::text[], array['Upper Back', 'Forearms']::text[], 'barbell', 'isolation', 'isolation', 'bilateral', array['Coge la barra del rack a la altura de los muslos con agarre prono a la anchura de los hombros.', 'Mantén los brazos estirados, el pecho alto y la barbilla neutra, sin mirar hacia arriba.', 'Eleva los hombros hacia las orejas en línea recta, aguanta un segundo y bájalos del todo.', 'Evita girar los hombros en círculos; el movimiento es solo arriba y abajo.', 'Saca la barra de un rack a media altura en lugar de levantarla desde el suelo.']::text[], '{}'::text[], true),
  ('barbell-stiff-leg-deadlift', 'Barbell Stiff-Leg Deadlift', 'Peso muerto con piernas rígidas con barra', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Glutes', 'Lower Back', 'Forearms']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Colócate con la barra sobre el centro del pie y las piernas casi rectas, sin bloquear.', 'Mantén la espalda neutra y las rodillas casi extendidas en todo el recorrido.', 'Baja la barra cerca de las piernas hasta el suelo o tu límite y sube extendiendo la cadera.', 'Evita tirar con la espalda redondeada para alcanzar el suelo.', 'Usa discos de tamaño normal o eleva la barra si no llegas al suelo con buena postura.']::text[], '{}'::text[], true),
  ('barbell-t-bar-row', 'Barbell T-Bar Row', 'Remo en T con barra', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps', 'Lower Back']::text[], 'barbell', 'pull horizontal', 'compound', 'bilateral', array['Colócate a horcajadas sobre la barra anclada, con un maneral en V bajo los discos y las rodillas flexionadas.', 'Mantén el torso inclinado unos 45° y la espalda neutra durante todo el tirón.', 'Tira del maneral hacia el pecho bajo llevando los codos atrás y baja hasta estirar los brazos.', 'Evita cargar demasiados discos grandes que te limiten el recorrido o te obliguen a balancearte.', 'Fija bien el extremo de la barra en el anclaje o en una esquina para que no se desplace.']::text[], '{}'::text[], true),
  ('barbell-upright-row', 'Barbell Upright Row', 'Remo al mentón con barra', 'Shoulders', 'Side Delts', array['Side Delts']::text[], array['Traps', 'Front Delts']::text[], 'barbell', 'pull vertical', 'compound', 'bilateral', array['Agarra la barra con las manos algo más anchas que los hombros, delante de los muslos.', 'Mantén el torso erguido y la barra cerca del cuerpo.', 'Sube la barra guiando con los codos hasta la parte baja del pecho y baja lento.', 'Evita subir la barra hasta la barbilla con agarre estrecho.', 'Detén el recorrido a la altura del pecho si notas molestia en la parte alta del hombro.']::text[], '{}'::text[], true),
  ('barbell-wrist-curl', 'Barbell Wrist Curl', 'Curl de muñeca con barra', 'Arms', 'Forearms', array['Forearms']::text[], '{}'::text[], 'barbell', 'isolation', 'isolation', 'bilateral', array['Siéntate con los antebrazos apoyados en los muslos o el banco y las palmas hacia arriba.', 'Mantén los antebrazos fijos y solo las muñecas por fuera del borde de apoyo.', 'Deja que la barra ruede hacia los dedos y súbela flexionando las muñecas lo más alto posible.', 'Evita levantar los antebrazos o usar los bíceps para mover la barra.', 'Trabaja con un peso moderado y repeticiones altas para cuidar las muñecas.']::text[], '{}'::text[], true),
  ('bb-bent-over-reverse-grip-rows', 'Barbell Bent-Over Row (Underhand Grip)', 'Remo inclinado con barra (agarre supino)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps', 'Lower Back']::text[], 'barbell', 'pull horizontal', 'compound', 'bilateral', array['Agarra la barra con las palmas hacia delante a la anchura de los hombros y bisagra la cadera.', 'Mantén el torso inclinado y fijo, con el abdomen firme y la barra cerca de los muslos.', 'Tira la barra hacia la parte baja del abdomen llevando los codos atrás y pegados al cuerpo.', 'Evita flexionar las muñecas o convertir el remo en un curl con los bíceps.', 'Sube la barra del suelo con la espalda neutra y las piernas, no tirando con la espalda redondeada.']::text[], '{}'::text[], true),
  ('bird-dog', 'Bird Dog', 'Perro de caza (bird dog)', 'Core', 'Abs', array['Abs', 'Lower Back']::text[], array['Glutes', 'Obliques']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Colócate a cuatro patas con manos bajo los hombros y rodillas bajo las caderas.', 'Mantén la espalda plana y la pelvis nivelada, como si llevaras un vaso encima.', 'Extiende el brazo y la pierna contrarios hasta la horizontal, pausa y vuelve despacio.', 'Evita arquear la zona lumbar o girar la cadera al levantar la pierna.', 'Muévete lento y sin prisas; la estabilidad importa más que la altura.']::text[], '{}'::text[], true),
  ('bodyweight-squat', 'Bodyweight Squat', 'Sentadilla con peso corporal', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'bodyweight', 'squat', 'compound', 'bilateral', array['Ponte de pie con los pies al ancho de hombros y los brazos al frente para equilibrarte.', 'Mantén la espalda recta y el peso repartido entre talón y antepié.', 'Baja hasta donde mantengas la técnica y sube a ritmo constante sin rebotar.', 'Evita levantar los talones o redondear la espalda al llegar abajo.', 'Realízala sobre un suelo antideslizante y con espacio libre a tu alrededor.']::text[], '{}'::text[], true),
  ('burpee', 'Burpee', 'Burpee', 'Full Body', 'Quads', array['Quads', 'Chest']::text[], array['Front Delts', 'Triceps', 'Abs', 'Glutes']::text[], 'bodyweight', 'squat', 'compound', 'bilateral', array['Ponte de pie con los pies a la anchura de la cadera y los brazos relajados.', 'Mantén el cuerpo alineado en la plancha, con la cadera ni hundida ni elevada.', 'Agáchate, salta a plancha, haz una flexión, vuelve los pies a las manos y salta arriba.', 'Evita aterrizar con las piernas rígidas o dejar caer el pecho al suelo sin control.', 'Aterriza suave con las rodillas flexionadas y baja el ritmo si pierdes la técnica.']::text[], '{}'::text[], true),
  ('cable-bayesian-curl', 'Cable Bayesian Curl', 'Curl bayesiano en polea', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Ponte de espaldas a una polea baja, sujeta el estribo y da un paso al frente con el brazo detrás.', 'Mantén el brazo por detrás del torso y el pecho abierto durante toda la repetición.', 'Flexiona el codo hasta arriba sin dejar que el brazo avance y vuelve al estiramiento lento.', 'Evita llevar el codo hacia delante al subir; pierdes el estiramiento que busca el ejercicio.', 'Usa una zancada estable para no perder el equilibrio cuando el cable tire hacia atrás.']::text[], '{}'::text[], true),
  ('cable-crunch', 'Cable Crunch (Kneeling)', 'Crunch en polea (de rodillas)', 'Core', 'Abs', array['Abs']::text[], array['Obliques']::text[], 'cable', 'core', 'isolation', 'bilateral', array['Arrodíllate frente a la polea alta y sujeta la cuerda a los lados de la cabeza.', 'Mantén la cadera quieta y alta; el movimiento debe salir de la columna.', 'Enrolla el tronco llevando los codos hacia los muslos y vuelve controlando el cable.', 'Evita sentarte sobre los talones o tirar del peso con los brazos.', 'Elige un peso que te permita flexionar el tronco sin tirones bruscos.']::text[], '{}'::text[], true),
  ('cable-curl-straight-bar', 'Cable Curl (Straight Bar)', 'Curl en polea (barra recta)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Coloca la polea abajo, sujeta la barra recta con palmas arriba y ponte cerca de la máquina.', 'Mantén los codos a los lados y el tronco erguido con las rodillas ligeramente flexionadas.', 'Sube la barra hasta el pecho, aprieta un segundo y baja resistiendo la tensión del cable.', 'Evita alejarte demasiado de la polea; el cable te tirará de los codos hacia delante.', 'Devuelve la barra a la polea con control al terminar, sin soltarla de golpe.']::text[], '{}'::text[], true),
  ('cable-face-pull', 'Cable Face Pull (Rope)', 'Face pull en polea (cuerda)', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back', 'Traps']::text[], 'cable', 'pull horizontal', 'compound', 'bilateral', array['Coloca la polea a la altura de la cara o un poco más alta y sujeta la cuerda con las palmas hacia abajo.', 'Mantén el torso erguido y estable, sin echarte hacia atrás.', 'Tira de la cuerda hacia la cara separando las manos y gira los hombros hacia fuera al final.', 'Evita tirar hacia el pecho como en un remo; las manos acaban a la altura de las orejas.', 'Usa un peso moderado que te permita controlar la rotación final.']::text[], '{}'::text[], true),
  ('cable-fly-low-to-high', 'Cable Fly (Low to High)', 'Aperturas en polea (de abajo hacia arriba)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Coloca las poleas en la posición más baja y da un paso adelante entre ellas.', 'Mantén el torso erguido, el pecho abierto y los codos ligeramente flexionados.', 'Sube las manos en arco hasta la altura de la barbilla y baja despacio.', 'No tires con los bíceps ni levantes los hombros al subir.', 'Coge y suelta los agarres con la polea en reposo para no perder el equilibrio.']::text[], '{}'::text[], true),
  ('cable-front-raise', 'Cable Front Raise', 'Elevaciones frontales en polea', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Upper Chest']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Ponte de espaldas a la polea baja con la cuerda o barra entre las piernas.', 'Mantén el torso erguido y los brazos casi extendidos.', 'Eleva el agarre al frente hasta la altura de los hombros y baja resistiendo el cable.', 'No dejes que el cable te tire hacia atrás al bajar.', 'Separa bien los pies para mantener el equilibrio frente a la tensión del cable.']::text[], '{}'::text[], true),
  ('cable-glute-kickback', 'Cable Glute Kickback', 'Patada de glúteo en polea', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Ajusta la tobillera a la polea baja y sujétate al soporte con el tronco algo inclinado.', 'Mantén la pelvis quieta y el abdomen firme mientras la pierna va hacia atrás.', 'Lleva la pierna atrás y arriba apretando el glúteo y regresa sin que el peso toque la pila.', 'Evita arquear la zona lumbar para llevar la pierna más alto.', 'Comprueba que la tobillera esté bien cerrada antes de empezar.']::text[], '{}'::text[], true),
  ('cable-hip-abduction', 'Cable Hip Abduction', 'Abducción de cadera en polea', 'Glutes', 'Abductors', array['Abductors', 'Glutes']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Ponte de lado a la polea baja con la tobillera en el pie más alejado.', 'Mantén el tronco recto sin inclinarte hacia el lado contrario al de la pierna.', 'Separa la pierna hacia fuera con la punta al frente y vuelve controlando el cable.', 'Evita girar la punta del pie hacia arriba, que cambia el músculo trabajado.', 'Sujétate a la máquina con la mano cercana para mantener el equilibrio.']::text[], '{}'::text[], true),
  ('cable-hip-adduction', 'Cable Hip Adduction', 'Aducción de cadera en polea', 'Legs', 'Adductors', array['Adductors']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Ponte de lado a la polea baja con la tobillera en el pie más cercano a la máquina.', 'Mantén la pierna de apoyo firme y la cadera mirando al frente.', 'Lleva la pierna por delante de la de apoyo cruzando la línea media y vuelve lento.', 'Evita inclinar el tronco para ayudar a cerrar la pierna.', 'Usa una carga ligera; los aductores se sobrecargan con facilidad.']::text[], '{}'::text[], true),
  ('cable-lat-pulldown-underhand-grip', 'Cable Lat Pulldown (Underhand Grip)', 'Jalón al pecho en polea (agarre supino)', 'Back', 'Lats', array['Lats']::text[], array['Biceps', 'Upper Back']::text[], 'cable', 'pull vertical', 'compound', 'bilateral', array['Agarra la barra recta con las palmas hacia ti, a la anchura de los hombros, y fija los muslos.', 'Mantén el pecho alto y una ligera inclinación atrás, sin arquear en exceso la zona lumbar.', 'Tira la barra hacia la parte baja del pecho llevando los codos junto al torso y sube con control.', 'Evita convertirlo en un curl de bíceps: piensa en bajar los codos, no en doblar las muñecas.', 'Usa un peso que puedas frenar en la subida sin que te levante del asiento.']::text[], '{}'::text[], true),
  ('cable-lateral-raise', 'Cable Lateral Raise (Single Arm)', 'Elevaciones laterales en polea (a una mano)', 'Shoulders', 'Side Delts', array['Side Delts']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Coloca la polea baja y agarra el estribo con la mano más alejada de la máquina.', 'Mantén el torso estable sujetándote a la máquina con la otra mano.', 'Eleva el brazo hacia el lado hasta la altura del hombro y baja controlando el cable.', 'No inclines el tronco para ganar recorrido.', 'Empieza con poco peso: la polea mantiene la tensión durante todo el recorrido.']::text[], '{}'::text[], true),
  ('cable-pallof-press', 'Cable Pallof Press', 'Press Pallof en polea', 'Core', 'Obliques', array['Obliques', 'Abs']::text[], '{}'::text[], 'cable', 'core', 'isolation', 'unilateral', array['Ponte de lado a una polea a la altura del pecho y sujeta el asa junto al esternón.', 'Mantén los pies a la anchura de la cadera, rodillas suaves y hombros cuadrados al frente.', 'Extiende los brazos al frente resistiendo el giro, pausa dos segundos y vuelve al pecho.', 'Evita que el tronco rote hacia la polea al extender los brazos.', 'Aléjate de la polea solo hasta donde puedas resistir la rotación sin perder la postura.']::text[], '{}'::text[], true),
  ('cable-pull-through', 'Cable Pull-Through', 'Pull-through en polea', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'cable', 'hinge', 'compound', 'bilateral', array['Ponte de espaldas a la polea baja con la cuerda entre las piernas y da dos pasos adelante.', 'Mantén los brazos estirados y la espalda neutra mientras llevas la cadera atrás.', 'Deja que la cuerda pase entre las piernas y extiende la cadera apretando los glúteos.', 'Evita tirar de la cuerda con los brazos o hacer una sentadilla.', 'Termina erguido sin hiperextender la zona lumbar al final.']::text[], '{}'::text[], true),
  ('cable-rear-delt-fly', 'Cable Rear Delt Fly', 'Pájaros en polea', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Coloca las poleas a la altura de los hombros y cruza los cables agarrando cada uno con la mano contraria.', 'Mantén los brazos casi extendidos y el pecho abierto.', 'Abre los brazos hacia atrás y afuera hasta la línea del cuerpo y vuelve lento.', 'Evita doblar los codos para convertirlo en un remo.', 'Da un paso atrás estable antes de empezar para no perder el equilibrio.']::text[], '{}'::text[], true),
  ('cable-rope-tricep-extensions', 'Cable Triceps Pushdown (Rope)', 'Extensión de tríceps en polea (cuerda)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Coloca la polea alta, sujeta la cuerda con palmas enfrentadas y lleva los codos a los costados.', 'Mantén el pecho alto, una ligera inclinación del tronco y los codos fijos junto a las costillas.', 'Empuja hacia abajo separando los extremos de la cuerda al final y sube con control.', 'Evita que los codos se abran o suban hacia delante al regresar la cuerda.', 'Mantén los hombros abajo y lejos de las orejas para no cargar el cuello.']::text[], '{}'::text[], true),
  ('cable-seated-row-underhand-grip', 'Cable Seated Row (Underhand Grip)', 'Remo sentado en polea (agarre supino)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'cable', 'pull horizontal', 'compound', 'bilateral', array['Agarra una barra recta con las palmas hacia arriba a la anchura de los hombros y siéntate erguido.', 'Mantén los codos pegados al cuerpo y el torso fijo durante el tirón.', 'Tira la barra hacia el ombligo llevando los codos atrás y deja que vuelva hasta estirar los brazos.', 'Evita levantar los codos o abrirlos; perderías el énfasis en los dorsales.', 'Mantén las muñecas rectas y alineadas con los antebrazos durante toda la serie.']::text[], '{}'::text[], true),
  ('cable-shrug', 'Cable Shrug', 'Encogimientos en polea', 'Back', 'Traps', array['Traps']::text[], array['Upper Back', 'Forearms']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Engancha una barra recta en la polea baja, agárrala en prono y ponte de pie cerca de la polea.', 'Mantén los brazos estirados y el torso vertical sin inclinarte hacia la polea.', 'Sube los hombros hacia las orejas con la tensión constante del cable y bájalos despacio.', 'Evita rebotar abajo; aprovecha que el cable mantiene la tensión durante todo el recorrido.', 'Coloca los pies firmes y lo bastante cerca para que el cable no te desequilibre hacia delante.']::text[], '{}'::text[], true),
  ('cable-straight-arms-pull-downs', 'Cable Straight-Arm Pulldown', 'Jalón con brazos rectos en polea', 'Back', 'Lats', array['Lats']::text[], array['Triceps', 'Rear Delts']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Colócate frente a la polea alta con una barra recta o cuerda, brazos estirados y torso algo inclinado.', 'Mantén los codos casi bloqueados y la espalda neutra, con la cadera ligeramente hacia atrás.', 'Lleva la barra en arco hasta los muslos apretando los dorsales y deja que suba hasta la altura de los ojos.', 'Evita doblar los codos y convertir el ejercicio en un press de tríceps.', 'Da un paso atrás tras enganchar la barra para que la carga no te arrastre al empezar.']::text[], array['straight-bb-straight-arms-pull-downs']::text[], true),
  ('cable-triceps-kickback', 'Cable Triceps Kickback', 'Patada de tríceps en polea', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Coloca la polea baja, sujeta el cable sin asa o con estribo e inclina el tronco al frente.', 'Mantén el brazo pegado al cuerpo y paralelo al suelo con la espalda recta.', 'Extiende el codo hacia atrás hasta bloquear y vuelve lento sin soltar la tensión.', 'Evita mover el hombro o el brazo; solo debe moverse el antebrazo.', 'Apoya la mano libre en la máquina para mantener la espalda estable.']::text[], '{}'::text[], true),
  ('cable-triceps-pushdown-reverse-grip', 'Cable Triceps Pushdown (Reverse Grip)', 'Extensión de tríceps en polea (agarre supino)', 'Arms', 'Triceps', array['Triceps']::text[], array['Forearms']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Coloca la polea alta y sujeta la barra con las palmas hacia arriba a la anchura de los hombros.', 'Mantén los codos junto al torso y las muñecas firmes, sin doblarlas hacia atrás.', 'Extiende los codos hasta abajo, aprieta el tríceps y vuelve despacio a 90 grados.', 'Evita mover los hombros hacia delante para sacar las últimas repeticiones.', 'Usa menos peso que con agarre prono para no sobrecargar las muñecas.']::text[], '{}'::text[], true),
  ('cable-triceps-pushdown-single-arm', 'Cable Triceps Pushdown (Single-Arm)', 'Extensión de tríceps en polea (a una mano)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'unilateral', array['Coloca la polea alta con un estribo y sujétalo con el codo pegado al costado.', 'Mantén los hombros nivelados y el torso de frente a la polea sin girarte.', 'Extiende el codo hasta abajo y vuelve con control hasta que el antebrazo pase la horizontal.', 'Evita que el codo se separe del cuerpo o que el hombro se adelante.', 'Apoya la mano libre en la máquina para mantener el equilibrio.']::text[], '{}'::text[], true),
  ('cable-triceps-pushdown-straight-bar', 'Cable Triceps Pushdown (Straight Bar)', 'Extensión de tríceps en polea (barra recta)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Coloca la polea alta y sujeta la barra recta con agarre prono a la anchura de los hombros.', 'Mantén los codos pegados a los costados y las muñecas alineadas con el antebrazo.', 'Empuja la barra hasta extender los codos por completo y sube hasta la altura del pecho.', 'Evita que la barra suba por encima del pecho y los codos se despeguen del cuerpo.', 'Mantén una postura estable con las rodillas flexionadas para no balancearte.']::text[], '{}'::text[], true),
  ('cable-upright-row', 'Cable Upright Row', 'Remo al mentón en polea', 'Shoulders', 'Side Delts', array['Side Delts']::text[], array['Traps', 'Front Delts']::text[], 'cable', 'pull vertical', 'compound', 'bilateral', array['Ponte frente a la polea baja con una barra recta o cuerda y agarre algo más ancho que los hombros.', 'Mantén la espalda recta y los hombros relajados al empezar.', 'Eleva los codos hacia los lados hasta la altura de los hombros y baja resistiendo el cable.', 'No eleves las muñecas por encima de los codos.', 'Usa un peso moderado; la polea no debe arrastrarte hacia delante.']::text[], '{}'::text[], true),
  ('cable-woodchop-high-to-low', 'Cable Woodchop (High to Low)', 'Leñador en polea (de arriba abajo)', 'Core', 'Obliques', array['Obliques']::text[], array['Abs', 'Front Delts']::text[], 'cable', 'core', 'compound', 'unilateral', array['Coloca la polea alta, ponte de lado y sujeta el asa con ambas manos por encima del hombro.', 'Mantén los brazos casi rectos y gira desde el tronco con la cadera acompañando.', 'Lleva el asa en diagonal hacia la rodilla contraria y vuelve controlando la rotación.', 'Evita tirar solo con los brazos o flexionar los codos para mover el cable.', 'Pivota el pie de atrás al girar para no forzar la rodilla ni la zona lumbar.']::text[], '{}'::text[], true),
  ('close-grip-bench-press', 'Barbell Bench Press (Close Grip)', 'Press de banca con barra (agarre cerrado)', 'Chest', 'Triceps', array['Triceps', 'Chest']::text[], array['Front Delts']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Agarra la barra con las manos a la anchura de los hombros, ni más juntas.', 'Mantén los codos pegados al cuerpo y las muñecas rectas sobre los antebrazos.', 'Baja la barra a la parte baja del pecho y extiende los codos empujando con los tríceps.', 'No juntes demasiado las manos: carga las muñecas sin trabajar más el tríceps.', 'Usa topes de seguridad ajustados a la altura del pecho si entrenas sin compañero.']::text[], array['close-grip-press']::text[], true),
  ('close-grip-decline-press', 'Barbell Bench Press (Decline, Close Grip)', 'Press de banca con barra (declinado, agarre cerrado)', 'Chest', 'Triceps', array['Triceps', 'Chest']::text[], array['Front Delts']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Fija los pies en los rodillos del banco declinado y agarra la barra a la anchura de los hombros.', 'Mantén los codos cerca del torso y la cabeza apoyada durante toda la serie.', 'Baja la barra hasta la parte inferior del pecho y empuja extendiendo los codos por completo.', 'Evita que los codos se abran hacia fuera al empujar.', 'Trabaja con un compañero que te ayude a sacar y devolver la barra en esta posición.']::text[], '{}'::text[], true),
  ('close-grip-dips', 'Dip (Close Grip)', 'Fondos en paralelas (agarre cerrado)', 'Chest', 'Triceps', array['Triceps']::text[], array['Chest', 'Front Delts']::text[], 'bodyweight', 'push vertical', 'compound', 'bilateral', array['Sujétate en paralelas estrechas con los brazos extendidos y el cuerpo vertical.', 'Mantén el torso erguido y los codos apuntando hacia atrás, pegados al cuerpo.', 'Baja hasta que los codos formen unos 90° y empuja hasta extender los brazos.', 'Evita encoger los hombros hacia las orejas en la parte baja.', 'No bajes más allá de lo que puedas controlar sin molestias en la parte delantera del hombro.']::text[], '{}'::text[], true),
  ('crunch', 'Crunch', 'Crunch abdominal', 'Core', 'Abs', array['Abs']::text[], '{}'::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Túmbate boca arriba con rodillas flexionadas, pies apoyados y manos junto a las sienes.', 'Mantén el cuello neutro, con un espacio de un puño entre la barbilla y el pecho.', 'Eleva los hombros del suelo contrayendo el abdomen y baja despacio.', 'Evita tirar de la cabeza con las manos para subir.', 'Exhala al subir y no retengas la respiración durante la serie.']::text[], '{}'::text[], true),
  ('db-60-y-raises', 'Dumbbell Y-Raise (Incline)', 'Elevaciones en Y con mancuernas (banco inclinado)', 'Shoulders', 'Side Delts', array['Side Delts']::text[], array['Rear Delts', 'Upper Back']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Túmbate boca abajo en un banco muy inclinado con las mancuernas colgando y los pulgares hacia arriba.', 'Mantén el pecho apoyado en el banco y el cuello neutro durante todo el movimiento.', 'Eleva los brazos en forma de Y por delante de la cabeza hasta la altura de las orejas y baja lento.', 'No encojas los hombros hacia las orejas ni despegues el pecho del banco.', 'Usa mancuernas ligeras: este ejercicio se resiente rápido con exceso de carga.']::text[], '{}'::text[], true),
  ('db-curls-offset-grip', 'Dumbbell Curl (Incline, Offset Grip)', 'Curl con mancuernas (inclinado, agarre descentrado)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Recuéstate en un banco inclinado con los brazos colgando y el meñique pegado al disco interior.', 'Mantén la espalda y la cabeza apoyadas y los brazos verticales detrás del torso.', 'Sube girando la palma hacia arriba sin adelantar el codo y baja hasta el estiramiento completo.', 'Evita despegar los hombros del banco o llevar los codos hacia delante al subir.', 'Baja siempre controlado: el estiramiento del bíceps en esta posición es intenso.']::text[], '{}'::text[], true),
  ('db-oh-press-neutral-grip', 'Dumbbell Shoulder Press (Neutral Grip)', 'Press de hombros con mancuernas (agarre neutro)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'dumbbell', 'push vertical', 'compound', 'bilateral', array['Coloca las mancuernas a la altura de los hombros con las palmas enfrentadas.', 'Mantén los codos delante del cuerpo y el tronco firme, sin inclinarte atrás.', 'Empuja en línea recta por encima de la cabeza y baja controlado hasta la barbilla.', 'Evita abrir los codos a los lados; con agarre neutro deben quedar al frente.', 'Usa un banco con respaldo si notas que te balanceas al empujar.']::text[], array['neutral-grip-db-oh-press']::text[], true),
  ('db-press-neutral-grip', 'Dumbbell Bench Press (Incline, Neutral Grip)', 'Press de banca con mancuernas (inclinado, agarre neutro)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'dumbbell', 'push horizontal', 'compound', 'bilateral', array['Túmbate en el banco inclinado con las palmas enfrentadas y las mancuernas sobre el pecho.', 'Mantén los codos cerca del torso y los antebrazos verticales durante todo el recorrido.', 'Baja hasta que las mancuernas rocen los laterales del pecho y empuja de forma controlada.', 'Evita girar las muñecas a mitad del movimiento; conserva las palmas enfrentadas.', 'Elige un peso que puedas controlar al bajar; si las mancuernas se balancean, reduce la carga.']::text[], '{}'::text[], true),
  ('db-pull-overs', 'Dumbbell Pullover', 'Pullover con mancuerna', 'Back', 'Lats', array['Lats']::text[], array['Chest', 'Triceps']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Túmbate en el banco y sujeta una mancuerna con ambas manos sobre el pecho, codos ligeramente flexionados.', 'Mantén las costillas abajo y la zona lumbar estable, sin arquearla al bajar el peso.', 'Lleva la mancuerna en arco detrás de la cabeza hasta notar estiramiento y regrésala sobre el pecho.', 'Evita flexionar y extender los codos en cada repetición; el ángulo del codo debe ser fijo.', 'Sujeta la mancuerna por debajo del disco superior con las manos entrelazadas para que no se suelte.']::text[], '{}'::text[], true),
  ('db-spider-hammer-curls', 'Dumbbell Spider Curl (Neutral Grip)', 'Curl araña con mancuernas (agarre neutro)', 'Arms', 'Biceps', array['Biceps', 'Forearms']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Túmbate boca abajo en un banco inclinado con el pecho apoyado y los brazos colgando verticales.', 'Mantén los brazos perpendiculares al suelo y las palmas enfrentadas durante toda la serie.', 'Sube las mancuernas sin mover los codos, aprieta arriba un segundo y baja lento.', 'Evita llevar los codos hacia atrás o hacia delante para ganar recorrido.', 'Apoya bien los pies y el pecho para que el banco no se desplace durante la serie.']::text[], '{}'::text[], true),
  ('db-walking-lunges-long-steps', 'Dumbbell Lunge (Walking)', 'Zancada con mancuernas (caminando)', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Hamstrings', 'Adductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Sujeta una mancuerna en cada mano a los lados y colócate en un pasillo despejado.', 'Mantén el torso erguido y la rodilla delantera alineada con el pie al avanzar.', 'Da un paso largo, baja hasta casi tocar el suelo con la rodilla trasera y avanza con la otra.', 'Evita dar pasos cortos que cargan la rodilla delantera y quitan trabajo al glúteo.', 'Asegura que el recorrido esté libre de obstáculos antes de empezar.']::text[], '{}'::text[], true),
  ('dead-bug', 'Dead Bug', 'Bicho muerto (dead bug)', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Obliques']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Túmbate boca arriba con brazos hacia el techo y caderas y rodillas a 90 grados.', 'Mantén la zona lumbar pegada al suelo durante todo el ejercicio.', 'Extiende el brazo y la pierna contrarios lentamente y vuelve antes de cambiar de lado.', 'Evita que la espalda baja se despegue del suelo al extender la pierna.', 'Reduce el recorrido de la pierna si no puedes mantener la espalda apoyada.']::text[], '{}'::text[], true),
  ('decline-bb-press', 'Barbell Bench Press (Decline)', 'Press de banca con barra (declinado)', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Engancha bien los pies bajo los rodillos antes de tumbarte en el banco declinado.', 'Mantén las escápulas juntas y la cabeza apoyada en todo momento.', 'Baja la barra hasta la parte inferior del pecho y empuja hasta extender los brazos sin bloquear de golpe.', 'Evita rebotar la barra sobre el esternón para subirla.', 'Pide ayuda para sacar y devolver la barra: la posición declinada dificulta engancharla solo.']::text[], '{}'::text[], true),
  ('decline-dumbbell-fly', 'Dumbbell Fly (Decline)', 'Aperturas con mancuernas (declinado)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Fija los pies en el banco declinado y sube las mancuernas sobre el pecho con las palmas enfrentadas.', 'Mantén los codos ligeramente flexionados y fijos durante todo el recorrido.', 'Abre los brazos en arco hasta notar estiramiento en el pecho y ciérralos sobre el esternón.', 'No bajes las mancuernas por debajo de la línea del banco.', 'Empieza con poco peso: en declive las mancuernas son más difíciles de controlar.']::text[], '{}'::text[], true),
  ('decline-sit-up', 'Sit-Up (Decline)', 'Abdominales (banco declinado)', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Obliques']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Engancha los pies en el banco declinado y túmbate con las manos cruzadas sobre el pecho.', 'Mantén la barbilla ligeramente recogida y el cuello relajado.', 'Sube enrollando el tronco vértebra a vértebra y baja despacio hasta casi tocar el banco.', 'Evita tirar de la cabeza con las manos o lanzarte con impulso.', 'Elige una inclinación que puedas controlar en la bajada antes de añadir peso.']::text[], '{}'::text[], true),
  ('dip', 'Dip', 'Fondos en paralelas', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'bodyweight', 'push vertical', 'compound', 'bilateral', array['Sube a las paralelas con los brazos extendidos y las piernas ligeramente hacia atrás.', 'Inclina el torso un poco hacia delante y mantén los hombros lejos de las orejas.', 'Baja hasta que los hombros queden a la altura de los codos y empuja hasta arriba.', 'No balancees las piernas para impulsarte en la subida.', 'Reduce el recorrido o usa asistencia si no controlas la parte baja.']::text[], '{}'::text[], true),
  ('dumbbell-arnold-press', 'Dumbbell Arnold Press', 'Press Arnold con mancuernas', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'dumbbell', 'push vertical', 'compound', 'bilateral', array['Siéntate con las mancuernas frente a la barbilla y las palmas mirando hacia ti.', 'Mantén la espalda apoyada y los codos al frente al empezar.', 'Gira las palmas hacia delante mientras empujas hacia arriba y deshaz el giro al bajar.', 'Evita separar el giro y el empuje en dos movimientos distintos.', 'Usa menos peso que en el press normal para controlar la rotación.']::text[], '{}'::text[], true),
  ('dumbbell-bench-press', 'Dumbbell Bench Press', 'Press de banca con mancuernas', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'dumbbell', 'push horizontal', 'compound', 'bilateral', array['Siéntate con las mancuernas en los muslos y túmbate llevándolas al pecho con ayuda de las rodillas.', 'Mantén las escápulas juntas y los antebrazos verticales sobre los codos.', 'Baja las mancuernas a los lados del pecho y súbelas en un ligero arco hacia el centro.', 'No dejes que las mancuernas se vayan hacia la cabeza o los pies al bajar.', 'Si una serie falla, baja las mancuernas al pecho y siéntate en vez de dejarlas caer abiertas.']::text[], '{}'::text[], true),
  ('dumbbell-bench-press-decline', 'Dumbbell Bench Press (Decline)', 'Press de banca con mancuernas (declinado)', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'dumbbell', 'push horizontal', 'compound', 'bilateral', array['Fija los pies en el banco declinado con las mancuernas apoyadas en el pecho antes de tumbarte.', 'Mantén la cabeza apoyada y las muñecas firmes sobre los codos.', 'Baja las mancuernas hacia la parte inferior del pecho y empuja hasta casi extender los brazos.', 'Evita arquear la espalda en exceso para levantar el peso.', 'Pide a un compañero que te pase las mancuernas si te cuesta colocarlas en declive.']::text[], '{}'::text[], true),
  ('dumbbell-bent-over-row', 'Dumbbell Bent-Over Row', 'Remo inclinado con mancuernas', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps', 'Lower Back']::text[], 'dumbbell', 'pull horizontal', 'compound', 'bilateral', array['Sujeta una mancuerna en cada mano, flexiona algo las rodillas e inclina el torso desde la cadera.', 'Mantén la espalda neutra y el peso del cuerpo repartido en todo el pie.', 'Tira ambas mancuernas hacia la cintura con los codos cerca del cuerpo y bájalas despacio.', 'Evita dejar caer la cabeza o redondear los hombros hacia delante al bajar.', 'Si notas la zona lumbar fatigada antes que la espalda alta, usa la versión con apoyo de pecho.']::text[], '{}'::text[], true),
  ('dumbbell-bulgarian-split-squat', 'Dumbbell Bulgarian Split Squat', 'Sentadilla búlgara con mancuernas', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors', 'Hamstrings']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Apoya el empeine trasero en un banco y coloca el pie delantero a un paso largo por delante.', 'Mantén la cadera cuadrada al frente y el peso sobre el pie delantero.', 'Baja en vertical hasta que el muslo delantero quede paralelo y sube sin rebotar.', 'Evita empujar con la pierna trasera; solo sirve de apoyo.', 'Ajusta la distancia al banco antes de coger peso para no perder el equilibrio.']::text[], '{}'::text[], true),
  ('dumbbell-chest-supported-row', 'Dumbbell Chest-Supported Row', 'Remo con mancuernas con apoyo de pecho', 'Back', 'Upper Back', array['Upper Back']::text[], array['Lats', 'Rear Delts', 'Biceps']::text[], 'dumbbell', 'pull horizontal', 'compound', 'bilateral', array['Túmbate boca abajo en un banco inclinado a unos 30-45° con una mancuerna en cada mano.', 'Mantén el pecho apoyado y las puntas de los pies firmes en el suelo para no deslizarte.', 'Rema llevando los codos atrás hasta juntar las escápulas y baja hasta estirar los brazos.', 'Evita estirar el cuello para mirar al frente; mantén la mirada hacia el suelo.', 'Al terminar, deja las mancuernas en el suelo antes de incorporarte del banco.']::text[], '{}'::text[], true),
  ('dumbbell-concentration-curl', 'Dumbbell Concentration Curl', 'Curl concentrado con mancuerna', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'unilateral', array['Siéntate en un banco con las piernas abiertas y apoya el tríceps en la cara interna del muslo.', 'Mantén el tronco inclinado y quieto, con la mano libre apoyada en la otra rodilla.', 'Sube la mancuerna hacia el hombro girando el meñique hacia arriba y baja despacio.', 'Evita usar la pierna o el tronco para empujar la mancuerna hacia arriba.', 'Baja hasta casi extender el codo sin dejar caer el peso en el último tramo.']::text[], '{}'::text[], true),
  ('dumbbell-curl-incline', 'Dumbbell Curl (Incline)', 'Curl con mancuernas (inclinado)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Ajusta el banco a unos 45-60 grados, apoya la espalda y deja los brazos colgando con palmas al frente.', 'Mantén los hombros pegados al respaldo y los codos apuntando al suelo.', 'Sube las mancuernas sin adelantar los codos y baja hasta estirar el bíceps por completo.', 'Evita despegar la cabeza o los hombros del banco al acercarte al final de la serie.', 'Empieza con poco peso: la posición estirada carga mucho la parte delantera del hombro.']::text[], '{}'::text[], true),
  ('dumbbell-farmers-carry', 'Dumbbell Farmer''s Carry', 'Paseo del granjero con mancuernas', 'Full Body', 'Forearms', array['Forearms', 'Traps']::text[], array['Abs', 'Obliques', 'Glutes']::text[], 'dumbbell', 'carry', 'compound', 'bilateral', array['Levanta una mancuerna pesada en cada mano con la espalda neutra y ponte de pie.', 'Mantén los hombros atrás, el pecho alto y la mirada al frente al caminar.', 'Camina con pasos cortos y firmes la distancia marcada sin detenerte.', 'Evita inclinarte hacia delante o dejar que los hombros se redondeen.', 'Deja una zona libre de obstáculos y suelta el peso flexionando cadera y rodillas.']::text[], '{}'::text[], true),
  ('dumbbell-farmers-hold', 'Dumbbell Farmer''s Hold', 'Sostén del granjero con mancuernas', 'Arms', 'Forearms', array['Forearms']::text[], array['Traps', 'Abs']::text[], 'dumbbell', 'carry', 'isolation', 'bilateral', array['Levanta dos mancuernas pesadas desde el suelo con la espalda neutra y quédate de pie.', 'Mantén los hombros abajo y atrás, el pecho alto y los brazos rectos a los lados.', 'Aprieta el mango con fuerza y sostén la posición el tiempo marcado sin moverte.', 'Evita encoger los hombros o dejar que las mancuernas se balanceen.', 'Al terminar, baja las mancuernas flexionando cadera y rodillas, no redondeando la espalda.']::text[], '{}'::text[], true),
  ('dumbbell-fly', 'Dumbbell Fly', 'Aperturas con mancuernas', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Túmbate en el banco plano con las mancuernas sobre el pecho y las palmas enfrentadas.', 'Mantén los codos ligeramente doblados y fijos, y las escápulas juntas.', 'Abre los brazos en arco hasta la altura del pecho y vuelve a cerrar como abrazando un árbol.', 'No uses mancuernas tan pesadas que tengas que doblar los codos y convertirlo en un press.', 'No bajes los brazos más allá de la línea de los hombros.']::text[], '{}'::text[], true),
  ('dumbbell-fly-incline', 'Dumbbell Fly (Incline)', 'Aperturas con mancuernas (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Ajusta el banco a una inclinación baja y sube las mancuernas sobre la parte alta del pecho.', 'Mantén el pecho alto y los codos con una flexión ligera y constante.', 'Abre los brazos hasta notar estiramiento y ciérralos en arco sobre las clavículas.', 'Evita que las mancuernas bajen hacia la cabeza en lugar de hacia los lados.', 'Controla especialmente la bajada; es donde el hombro está más expuesto.']::text[], '{}'::text[], true),
  ('dumbbell-front-raise', 'Dumbbell Front Raise', 'Elevaciones frontales con mancuernas', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Upper Chest']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Ponte de pie con las mancuernas delante de los muslos y las palmas hacia ti.', 'Mantén el abdomen firme y los codos ligeramente flexionados.', 'Eleva las mancuernas al frente hasta la altura de los hombros y baja lento.', 'Evita echar el cuerpo hacia atrás para subir el peso.', 'Deja de subir a la altura de los ojos; ir más arriba no aporta más trabajo útil.']::text[], '{}'::text[], true),
  ('dumbbell-goblet-squat', 'Dumbbell Goblet Squat', 'Sentadilla goblet con mancuerna', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors', 'Abs']::text[], 'dumbbell', 'squat', 'compound', 'bilateral', array['Sujeta una mancuerna vertical contra el pecho, con los pies algo más abiertos que los hombros.', 'Mantén la mancuerna pegada al pecho y el tronco erguido mientras bajas.', 'Baja hasta que los codos rocen el interior de las rodillas y sube empujando con los talones.', 'Evita separar la mancuerna del cuerpo, porque te tira el tronco hacia delante.', 'Elige un peso que puedas sostener con firmeza todo el set sin que resbale.']::text[], '{}'::text[], true),
  ('dumbbell-lateral-raise-seated', 'Dumbbell Lateral Raise (Seated)', 'Elevaciones laterales con mancuernas (sentado)', 'Shoulders', 'Side Delts', array['Side Delts']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Siéntate en el borde de un banco con las mancuernas a los lados y los pies apoyados.', 'Mantén el torso erguido y los hombros bajos, lejos de las orejas.', 'Sube los brazos hacia los lados hasta la altura de los hombros y baja despacio.', 'Evita girar las mancuernas como si vertieras agua con el pulgar hacia abajo.', 'Trabaja con un peso ligero que te permita una pausa breve arriba.']::text[], '{}'::text[], true),
  ('dumbbell-lunge-curtsy', 'Dumbbell Lunge (Curtsy)', 'Zancada con mancuerna (cruzada)', 'Glutes', 'Glutes', array['Glutes']::text[], array['Quads', 'Adductors', 'Abductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Sujeta una mancuerna contra el pecho con los pies a la anchura de cadera.', 'Mantén la cadera mirando al frente aunque la pierna trasera se cruce por detrás.', 'Cruza un pie en diagonal hacia atrás, baja con control y vuelve empujando con la pierna delantera.', 'Evita girar el tronco o la pelvis hacia el lado de la pierna que cruza.', 'Limita la amplitud del cruce si notas que pierdes el equilibrio.']::text[], '{}'::text[], true),
  ('dumbbell-lunge-forward', 'Dumbbell Lunge (Forward)', 'Zancada con mancuernas (hacia delante)', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Hamstrings', 'Adductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Ponte de pie con los pies a la anchura de cadera y una mancuerna en cada mano.', 'Mantén el pecho alto y el peso repartido sobre el pie delantero al aterrizar.', 'Da un paso adelante, baja con control y empuja con el talón delantero para volver.', 'Evita aterrizar con un golpe seco sobre el talón o con el pie demasiado cerca.', 'Usa una carga moderada; el frenado hacia delante exige mucho control.']::text[], '{}'::text[], true),
  ('dumbbell-lunge-lateral', 'Dumbbell Lunge (Lateral)', 'Zancada con mancuerna (lateral)', 'Legs', 'Adductors', array['Adductors', 'Glutes']::text[], array['Quads']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Ponte de pie con los pies juntos sosteniendo una mancuerna contra el pecho.', 'Mantén la pierna estirada recta y el pie de apoyo totalmente plano.', 'Da un paso lateral amplio, lleva la cadera atrás sobre esa pierna y empuja para volver.', 'Evita que la rodilla flexionada se adelante mucho por delante de la punta del pie.', 'Aumenta la amplitud del paso de forma progresiva según tu movilidad de aductores.']::text[], '{}'::text[], true),
  ('dumbbell-lunge-reverse', 'Dumbbell Lunge (Reverse)', 'Zancada con mancuernas (hacia atrás)', 'Legs', 'Glutes', array['Glutes', 'Quads']::text[], array['Hamstrings', 'Adductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Colócate de pie con las mancuernas a los costados y el peso en el pie de apoyo.', 'Mantén la tibia delantera casi vertical y el tronco ligeramente inclinado.', 'Lleva una pierna atrás, baja la rodilla cerca del suelo y vuelve empujando con el pie delantero.', 'Evita apoyar el pie trasero sobre la misma línea, que te desequilibra.', 'Apoya la rodilla trasera con suavidad, nunca la golpees contra el suelo.']::text[], '{}'::text[], true),
  ('dumbbell-overhead-triceps-extension', 'Dumbbell Overhead Triceps Extension (Seated)', 'Extensión de tríceps sobre la cabeza con mancuerna (sentado)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Siéntate en un banco con respaldo y sujeta una mancuerna con ambas manos por encima de la cabeza.', 'Mantén la espalda apoyada, las costillas abajo y los codos apuntando al frente.', 'Baja la mancuerna detrás de la cabeza hasta sentir el estiramiento y extiende los codos.', 'Evita arquear la zona lumbar cuando la mancuerna está arriba.', 'Sujeta bien el disco superior con ambas palmas para que la mancuerna no se deslice.']::text[], '{}'::text[], true),
  ('dumbbell-overhead-triceps-extension-single-arm', 'Dumbbell Overhead Triceps Extension (Single-Arm)', 'Extensión de tríceps sobre la cabeza con mancuerna (a una mano)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'unilateral', array['Sujeta la mancuerna con un brazo extendido sobre la cabeza, sentado o de pie con el abdomen firme.', 'Mantén el codo apuntando al techo y cerca de la cabeza; la otra mano puede sujetarlo.', 'Baja la mancuerna detrás de la nuca flexionando el codo y vuelve a extender por completo.', 'Evita que el codo se vaya hacia fuera o que el tronco se incline hacia un lado.', 'Trabaja con un peso ligero que controles; la mancuerna pasa por detrás de la cabeza.']::text[], '{}'::text[], true),
  ('dumbbell-rear-delt-fly', 'Dumbbell Rear Delt Fly (Bent-Over)', 'Pájaros con mancuernas (inclinado)', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Inclínate desde la cadera con la espalda recta y las mancuernas colgando bajo el pecho.', 'Mantén la espalda neutra y el cuello alineado con el torso.', 'Abre los brazos hacia los lados con los codos algo flexionados y baja despacio.', 'Evita juntar las escápulas en exceso; el movimiento debe salir del hombro.', 'Si te cuesta mantener la espalda recta, apoya la frente en un banco inclinado.']::text[], '{}'::text[], true),
  ('dumbbell-rear-delt-fly-chest-supported', 'Dumbbell Rear Delt Fly (Chest-Supported)', 'Pájaros con mancuernas (pecho apoyado)', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Túmbate boca abajo en un banco inclinado con las mancuernas colgando y las palmas enfrentadas.', 'Mantén el pecho pegado al banco y la barbilla neutra.', 'Eleva los brazos hacia los lados hasta la línea de los hombros y baja con control.', 'No despegues el pecho del banco para ganar impulso.', 'Usa mancuernas ligeras y prioriza el control sobre la carga.']::text[], '{}'::text[], true),
  ('dumbbell-romanian-deadlift', 'Dumbbell Romanian Deadlift', 'Peso muerto rumano con mancuernas', 'Legs', 'Hamstrings', array['Hamstrings', 'Glutes']::text[], array['Lower Back', 'Forearms']::text[], 'dumbbell', 'hinge', 'compound', 'bilateral', array['Sujeta una mancuerna en cada mano delante de los muslos con los pies al ancho de cadera.', 'Mantén las mancuernas pegadas a las piernas y los hombros hacia atrás.', 'Empuja la cadera atrás bajando las mancuernas por las tibias y vuelve apretando glúteos.', 'Evita dejar que las mancuernas se separen del cuerpo y cuelguen hacia delante.', 'Detén la bajada cuando la espalda empiece a redondearse.']::text[], '{}'::text[], true),
  ('dumbbell-romanian-deadlift-single-leg', 'Dumbbell Romanian Deadlift (Single-Leg)', 'Peso muerto rumano con mancuerna (a una pierna)', 'Glutes', 'Hamstrings', array['Hamstrings', 'Glutes']::text[], array['Lower Back', 'Abductors']::text[], 'dumbbell', 'hinge', 'compound', 'unilateral', array['Ponte sobre una pierna con la rodilla algo flexionada y la mancuerna en la mano contraria.', 'Mantén la cadera nivelada y la pierna libre alineada con el tronco al inclinarte.', 'Inclínate hasta que el tronco quede casi paralelo al suelo y vuelve empujando con el talón.', 'Evita abrir la cadera de la pierna trasera hacia el techo.', 'Toca una pared o un soporte con la mano libre si necesitas más equilibrio.']::text[], '{}'::text[], true),
  ('dumbbell-row-single-arm', 'Dumbbell Row (Single-Arm)', 'Remo con mancuerna (a una mano)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Rear Delts', 'Biceps']::text[], 'dumbbell', 'pull horizontal', 'compound', 'unilateral', array['Apoya una rodilla y una mano en el banco, con la mancuerna colgando bajo el hombro del brazo libre.', 'Mantén la espalda plana y paralela al suelo, con los hombros a la misma altura.', 'Lleva la mancuerna hacia la cadera rozando el costado y bájala hasta estirar el dorsal.', 'Evita rotar el torso hacia arriba en cada repetición para levantar más peso.', 'Recoge y deja la mancuerna en el suelo con la espalda neutra y apoyado en el banco.']::text[], '{}'::text[], true),
  ('dumbbell-shoulder-press', 'Dumbbell Shoulder Press (Seated)', 'Press de hombros con mancuernas (sentado)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'dumbbell', 'push vertical', 'compound', 'bilateral', array['Siéntate en un banco con respaldo casi vertical y lleva las mancuernas a la altura de los hombros.', 'Mantén la espalda apoyada, el abdomen firme y las muñecas sobre los codos.', 'Empuja las mancuernas hacia arriba hasta casi juntarlas y baja hasta la altura de las orejas.', 'No arquees la zona lumbar para despegar la espalda del respaldo.', 'Sube las mancuernas a los hombros apoyándolas primero en las rodillas.']::text[], '{}'::text[], true),
  ('dumbbell-shoulder-press-standing', 'Dumbbell Shoulder Press (Standing)', 'Press de hombros con mancuernas (de pie)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps', 'Abs']::text[], 'dumbbell', 'push vertical', 'compound', 'bilateral', array['Ponte de pie con los pies a la anchura de la cadera y las mancuernas sobre los hombros.', 'Aprieta abdomen y glúteos para no arquear la espalda baja.', 'Empuja las mancuernas sobre la cabeza y bájalas controladas hasta las orejas.', 'No impulses el peso con las piernas salvo que hagas un push press intencionado.', 'Elige un peso menor que en la versión sentada: la estabilidad es más exigente.']::text[], '{}'::text[], true),
  ('dumbbell-shrug', 'Dumbbell Shrug', 'Encogimientos con mancuernas', 'Back', 'Traps', array['Traps']::text[], array['Upper Back', 'Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Ponte de pie con una mancuerna a cada lado y las palmas mirando hacia el cuerpo.', 'Mantén los brazos relajados y estirados, con el cuello largo y la mirada al frente.', 'Sube los hombros lo más alto posible, haz una pausa breve arriba y baja hasta estirar el trapecio.', 'Evita doblar los codos para ayudarte; los brazos solo funcionan como ganchos.', 'Usa correas si el agarre falla antes que el trapecio en lugar de soltar las mancuernas.']::text[], '{}'::text[], true),
  ('dumbbell-skull-crusher', 'Dumbbell Skull Crusher', 'Press francés con mancuernas', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Túmbate en un banco plano con una mancuerna en cada mano, palmas enfrentadas y brazos extendidos.', 'Mantén los brazos fijos y paralelos entre sí durante todo el movimiento.', 'Baja las mancuernas a los lados de la cabeza flexionando los codos y extiéndelos hasta arriba.', 'Evita que las mancuernas se separen o que los codos se abran al subir.', 'Baja despacio y sostén bien las mancuernas para no golpearte la cabeza.']::text[], '{}'::text[], true),
  ('dumbbell-split-squat', 'Dumbbell Split Squat', 'Sentadilla dividida con mancuernas', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors', 'Hamstrings']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Colócate en posición de zancada con los dos pies en el suelo y mancuernas a los lados.', 'Mantén los pies separados a lo ancho de cadera, como sobre dos raíles.', 'Baja la rodilla trasera hacia el suelo sin mover los pies y sube a la posición inicial.', 'Evita que la rodilla delantera se cierre hacia dentro al subir.', 'Desciende con control para no golpear la rodilla trasera contra el suelo.']::text[], '{}'::text[], true),
  ('dumbbell-standing-calf-raise-single-leg', 'Dumbbell Standing Calf Raise (Single-Leg)', 'Elevación de talón de pie con mancuerna (a una pierna)', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'unilateral', array['Ponte sobre un escalón con un pie, la mancuerna en la mano de ese lado y la otra mano en un apoyo.', 'Mantén la rodilla de apoyo extendida y el tobillo alineado, sin vencerse hacia fuera.', 'Baja el talón por debajo del escalón y sube lo más alto posible con control.', 'Evita apoyarte demasiado en la mano libre para ayudarte a subir.', 'Usa un escalón firme y sujétate siempre a algo estable.']::text[], '{}'::text[], true),
  ('dumbbell-step-up', 'Dumbbell Step-Up', 'Subida al cajón con mancuernas', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Hamstrings', 'Adductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Coloca un pie entero sobre un cajón a la altura de la rodilla con mancuernas a los lados.', 'Mantén el torso ligeramente inclinado y la rodilla de apoyo en línea con el pie.', 'Sube empujando solo con la pierna de arriba y baja lento hasta tocar el suelo.', 'Evita impulsarte con la pierna de abajo para ayudarte a subir.', 'Usa un cajón estable y antideslizante; nunca uno que pueda volcar.']::text[], '{}'::text[], true),
  ('dumbbell-suitcase-carry', 'Dumbbell Suitcase Carry', 'Paseo de maleta con mancuerna', 'Full Body', 'Obliques', array['Obliques', 'Forearms']::text[], array['Abs', 'Traps', 'Glutes']::text[], 'dumbbell', 'carry', 'compound', 'unilateral', array['Sujeta una sola mancuerna a un lado, como una maleta, con el brazo extendido.', 'Mantén los hombros nivelados y el tronco vertical sin inclinarte hacia el peso.', 'Camina a paso controlado la distancia marcada y repite con el otro lado.', 'Evita compensar inclinándote hacia el lado contrario a la mancuerna.', 'Empieza con un peso moderado; la estabilidad lateral es lo que se entrena.']::text[], '{}'::text[], true),
  ('dumbbell-sumo-squat', 'Dumbbell Sumo Squat', 'Sentadilla sumo con mancuerna', 'Legs', 'Adductors', array['Adductors', 'Glutes']::text[], array['Quads']::text[], 'dumbbell', 'squat', 'compound', 'bilateral', array['Abre los pies bien por fuera de los hombros con las puntas hacia afuera y sujeta la mancuerna colgando.', 'Mantén el tronco vertical y empuja las rodillas hacia afuera, en la línea de los pies.', 'Baja dejando la mancuerna entre las piernas y sube apretando glúteos e interior del muslo.', 'Evita abrir tanto la postura que las rodillas no puedan seguir a las puntas.', 'Sube a un escalón o disco si la mancuerna toca el suelo antes de tu rango completo.']::text[], '{}'::text[], true),
  ('dumbbell-thruster', 'Dumbbell Thruster', 'Thruster con mancuernas', 'Full Body', 'Quads', array['Quads', 'Front Delts']::text[], array['Glutes', 'Triceps', 'Abs']::text[], 'dumbbell', 'squat', 'compound', 'bilateral', array['Sujeta las mancuernas sobre los hombros con codos al frente y pies al ancho de la cadera.', 'Mantén el pecho alto y el tronco firme durante la sentadilla.', 'Baja en sentadilla y, al subir, usa el impulso de piernas para empujar las mancuernas arriba.', 'Evita separar la sentadilla del press; el movimiento debe ser continuo.', 'Bloquea los brazos arriba con las costillas abajo para no arquear la zona lumbar.']::text[], '{}'::text[], true),
  ('dumbbell-triceps-kickback', 'Dumbbell Triceps Kickback', 'Patada de tríceps con mancuerna', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'unilateral', array['Apoya una mano y una rodilla en el banco con la espalda plana y la mancuerna en la otra mano.', 'Mantén el brazo paralelo al suelo y el codo pegado al costado durante toda la serie.', 'Extiende el codo hasta que el brazo quede recto, aprieta un segundo y vuelve despacio.', 'Evita que el codo baje al extender o balancear la mancuerna con impulso.', 'Mantén la espalda neutra y no gires el tronco al mover el brazo.']::text[], '{}'::text[], true),
  ('ez-bar-curl', 'EZ-Bar Curl', 'Curl con barra Z', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'ez-bar', 'isolation', 'isolation', 'bilateral', array['Sujeta la barra Z en las curvas interiores o exteriores con las palmas semisupinadas.', 'Mantén el pecho alto y los codos justo delante de las costillas.', 'Flexiona los codos hasta que la barra llegue cerca del pecho y baja hasta casi extender.', 'Evita encoger los hombros o llevar los codos hacia arriba al final del recorrido.', 'Mantén la espalda neutra; no compenses el peso inclinándote hacia atrás.']::text[], '{}'::text[], true),
  ('ez-bar-overhead-triceps-extension', 'EZ-Bar Overhead Triceps Extension', 'Extensión de tríceps sobre la cabeza con barra Z', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'ez-bar', 'isolation', 'isolation', 'bilateral', array['Sujeta la barra Z con agarre cerrado y llévala sobre la cabeza con los brazos extendidos.', 'Mantén los codos estrechos y apuntando al frente, con las costillas abajo.', 'Baja la barra detrás de la cabeza hasta el estiramiento y extiende sin mover los brazos.', 'Evita compensar la subida arqueando la espalda o abriendo los codos.', 'Hazlo sentado con respaldo si notas que la zona lumbar se arquea de pie.']::text[], '{}'::text[], true),
  ('ez-bar-pullover', 'EZ-Bar Pullover', 'Pullover con barra EZ', 'Back', 'Lats', array['Lats']::text[], array['Chest', 'Triceps']::text[], 'ez-bar', 'isolation', 'isolation', 'bilateral', array['Túmbate en un banco plano con la barra EZ sobre el pecho y un agarre estrecho en prono.', 'Mantén la cabeza apoyada, los pies firmes y los codos algo flexionados durante todo el arco.', 'Baja la barra por detrás de la cabeza hasta sentir el estiramiento y súbela hasta encima del pecho.', 'Evita bajar más allá de donde controlas la barra o arquear la espalda para alcanzar más recorrido.', 'Usa una carga moderada; la barra pasa sobre tu cara y debes poder frenarla en todo momento.']::text[], '{}'::text[], true),
  ('ez-bar-skull-crusher', 'EZ-Bar Skull Crusher', 'Press francés con barra Z', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'ez-bar', 'isolation', 'isolation', 'bilateral', array['Túmbate en un banco plano con la barra Z sobre los hombros y los brazos extendidos.', 'Mantén los codos apuntando al techo y ligeramente inclinados hacia la cabeza.', 'Baja la barra hacia la frente o detrás de la cabeza flexionando solo los codos y vuelve a subir.', 'Evita abrir los codos hacia fuera o convertir el movimiento en un press.', 'Pide ayuda o usa un peso controlable: la barra pasa cerca de la cara.']::text[], '{}'::text[], true),
  ('ez-bb-preacher-curls', 'EZ-Bar Preacher Curl', 'Curl predicador con barra Z', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'ez-bar', 'isolation', 'isolation', 'bilateral', array['Ajusta el asiento para que las axilas queden pegadas al borde superior del cojín predicador.', 'Mantén la parte trasera de los brazos apoyada en el cojín durante toda la serie.', 'Sube la barra Z hasta contraer el bíceps y baja en 2-3 segundos hasta casi extender los codos.', 'Evita levantar los codos del cojín o echar los hombros hacia delante para subir la barra.', 'No dejes caer la barra en el fondo: controla la extensión final para no forzar el codo.']::text[], '{}'::text[], true),
  ('ffe-db-split-squats', 'Dumbbell Split Squat (Front-Foot-Elevated)', 'Sentadilla dividida con mancuernas (pie delantero elevado)', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'dumbbell', 'lunge', 'compound', 'unilateral', array['Apoya el pie delantero sobre un disco o step bajo y coloca el pie trasero atrás.', 'Mantén el torso erguido y deja que la rodilla delantera avance sobre el pie.', 'Baja profundo aprovechando la elevación y sube empujando con el pie delantero.', 'Evita usar una plataforma alta o inestable que te saque del equilibrio.', 'Verifica que el disco o step no se deslice antes de añadir carga.']::text[], '{}'::text[], true),
  ('glute-bridge', 'Glute Bridge', 'Puente de glúteo', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'bodyweight', 'hinge', 'compound', 'bilateral', array['Túmbate boca arriba con las rodillas flexionadas y los pies planos al ancho de cadera.', 'Mantén la pelvis ligeramente retroversa y el abdomen activo durante la subida.', 'Sube la cadera apretando glúteos hasta formar una línea recta y baja lento.', 'Evita empujar con la espalda baja en lugar de con los glúteos.', 'Realízalo sobre una colchoneta para proteger la columna del suelo duro.']::text[], '{}'::text[], true),
  ('glute-bridge-single-leg', 'Glute Bridge (Single-Leg)', 'Puente de glúteo (a una pierna)', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'bodyweight', 'hinge', 'compound', 'unilateral', array['Túmbate boca arriba con un pie apoyado cerca del glúteo y la otra pierna estirada en el aire.', 'Mantén ambas caderas a la misma altura durante todo el movimiento.', 'Eleva la cadera empujando con el talón de apoyo, pausa arriba y baja sin apoyarte del todo.', 'Evita que la cadera de la pierna libre se hunda al subir.', 'Detén la serie si notas calambre en los isquios y acerca más el pie al glúteo.']::text[], '{}'::text[], true),
  ('hack-squat-machine', 'Plate-Loaded Hack Squat', 'Sentadilla hack en máquina de discos', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Adductors']::text[], 'plate-loaded', 'squat', 'compound', 'bilateral', array['Apoya espalda y hombros en las almohadillas con los pies a la mitad de la plataforma.', 'Mantén la cadera y la espalda baja pegadas al respaldo en todo el recorrido.', 'Baja hasta que los muslos pasen el paralelo y sube sin bloquear las rodillas arriba.', 'Evita colocar los pies tan altos que pierdas el trabajo de cuádriceps.', 'Quita y pon los seguros de la máquina con las piernas ya extendidas.']::text[], array['hack-squats']::text[], true),
  ('hammer-curls', 'Dumbbell Hammer Curl', 'Curl martillo con mancuernas', 'Arms', 'Biceps', array['Biceps', 'Forearms']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Ponte de pie con las mancuernas a los lados y las palmas mirándose entre sí.', 'Mantén las muñecas rectas y los codos pegados al cuerpo durante todo el recorrido.', 'Sube la mancuerna como un martillo hasta el hombro y baja en 2-3 segundos.', 'Evita girar la palma hacia arriba o mover el hombro hacia delante al subir.', 'No balancees el tronco; si pierdes la postura, reduce el peso.']::text[], '{}'::text[], true),
  ('hanging-knee-raise', 'Hanging Knee Raise', 'Elevación de rodillas colgado', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Forearms']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Cuélgate de una barra con agarre al ancho de hombros y piernas relajadas.', 'Mantén los hombros activos y el cuerpo estable sin columpiarte.', 'Sube las rodillas hacia el pecho inclinando la pelvis hacia arriba y baja lento.', 'Evita quedarte en subir las rodillas a 90 grados sin enrollar la pelvis.', 'Baja de la barra con control si se te fatiga el agarre antes que el abdomen.']::text[], '{}'::text[], true),
  ('hanging-leg-raises-weighted', 'Hanging Leg Raise', 'Elevación de piernas colgado', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Obliques', 'Forearms']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Cuélgate de la barra con agarre firme, brazos extendidos y las piernas juntas.', 'Mantén los hombros activos y el cuerpo quieto, sin columpiarte antes de empezar.', 'Sube las piernas rectas enrollando la pelvis hacia arriba y bájalas en 2-3 segundos.', 'Evita usar el impulso del balanceo para subir las piernas.', 'Si aún no controlas el balanceo, empieza con elevaciones de rodillas.']::text[], '{}'::text[], true),
  ('heels-elevated-hb-squats', 'Barbell Back Squat (High Bar, Heels Elevated)', 'Sentadilla trasera con barra (barra alta, talones elevados)', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Adductors']::text[], 'barbell', 'squat', 'compound', 'bilateral', array['Coloca los talones sobre un disco o cuña y la barra alta sobre los trapecios.', 'Mantén el torso lo más vertical posible y deja que las rodillas avancen sobre los pies.', 'Desciende profundo y lento, y sube sin despegar los talones de la cuña.', 'Evita usar una cuña tan alta que el peso se vaya a las puntas de los pies.', 'Asegura que la cuña esté firme y no se deslice antes de cargar la barra.']::text[], '{}'::text[], true),
  ('hex-bar-deadlift', 'Hex-Bar Deadlift', 'Peso muerto con barra hexagonal', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Hamstrings', 'Lower Back', 'Traps', 'Forearms']::text[], 'hex-bar', 'hinge', 'compound', 'bilateral', array['Colócate en el centro de la barra hexagonal con los pies al ancho de cadera y agarra las asas.', 'Mantén los brazos estirados, el pecho alto y la espalda neutra al subir.', 'Empuja el suelo hasta quedar erguido y baja la barra controlando la cadera y las rodillas.', 'Evita descentrarte dentro de la barra, que la inclina hacia delante o atrás.', 'Revisa que los discos estén asegurados con collarines antes de levantar.']::text[], '{}'::text[], true),
  ('hex-bar-shrug', 'Hex-Bar Shrug', 'Encogimientos con barra hexagonal', 'Back', 'Traps', array['Traps']::text[], array['Upper Back', 'Forearms']::text[], 'hex-bar', 'isolation', 'isolation', 'bilateral', array['Colócate dentro de la barra hexagonal, agarra las asas altas y levántala con las piernas.', 'Mantén el torso erguido y los hombros alineados con las asas, sin inclinarte.', 'Encoge los hombros verticalmente, sostén arriba y bájalos de forma controlada.', 'Evita echar los hombros hacia delante; piensa en llevarlos hacia las orejas en vertical.', 'Levanta y deja la barra en el suelo con la espalda neutra, igual que en un peso muerto.']::text[], '{}'::text[], true),
  ('high-cable-fly', 'Cable Fly (High to Low)', 'Aperturas en polea (de arriba hacia abajo)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Coloca las poleas en la posición más alta y adelanta un pie para tener una base estable.', 'Inclina ligeramente el torso hacia delante y mantén el pecho abierto.', 'Lleva las manos hacia abajo y al centro, a la altura de la cadera, y sube despacio.', 'Evita encorvar los hombros hacia delante al juntar las manos.', 'Usa un peso que te permita volver sin que los cables te tiren de los brazos hacia atrás.']::text[], '{}'::text[], true),
  ('hip-thrust-single-leg', 'Hip Thrust (Single-Leg)', 'Hip thrust (a una pierna)', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'bodyweight', 'hinge', 'compound', 'unilateral', array['Apoya la espalda alta en un banco con un pie en el suelo y la otra rodilla al pecho.', 'Mantén la pelvis nivelada sin que caiga hacia el lado de la pierna libre.', 'Empuja con el talón de apoyo hasta extender la cadera y baja de forma controlada.', 'Evita girar la cadera para ganar altura en la subida.', 'Coloca el banco contra una pared para que no se desplace.']::text[], '{}'::text[], true),
  ('hollow-body-hold', 'Hollow Body Hold', 'Posición hueca (hollow hold)', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors', 'Obliques']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Túmbate boca arriba con brazos sobre la cabeza y piernas juntas extendidas.', 'Mantén la zona lumbar pegada al suelo y los hombros despegados.', 'Eleva brazos y piernas unos centímetros y sostén la forma de banana respirando.', 'Evita que la espalda baja se arquee al bajar las piernas.', 'Flexiona las rodillas o sube las piernas si no consigues mantener la lumbar apoyada.']::text[], '{}'::text[], true),
  ('hor-back-extensions-glutes-dominant', 'Back Extension (Horizontal, Glute Focus)', 'Hiperextensión (horizontal, enfoque glúteo)', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings', 'Lower Back']::text[], 'bodyweight', 'hinge', 'compound', 'bilateral', array['Ajusta el apoyo justo por debajo de la cadera para que pueda flexionarse libremente.', 'Mantén la parte alta de la espalda ligeramente redondeada y la mirada al suelo.', 'Baja flexionando la cadera y sube apretando los glúteos hasta alinear el cuerpo.', 'Evita subir arqueando la zona lumbar por encima de la línea del cuerpo.', 'Sube de forma controlada, sin balanceos que tiren de la espalda baja.']::text[], '{}'::text[], true),
  ('incline-barbell-bench-press', 'Barbell Bench Press (Incline)', 'Press de banca con barra (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'barbell', 'push horizontal', 'compound', 'bilateral', array['Ajusta el banco a una inclinación moderada y colócate con la barra sobre los ojos.', 'Mantén las escápulas retraídas y el pecho alto sin despegar los glúteos del asiento.', 'Baja la barra a la parte alta del pecho, bajo las clavículas, y empuja en línea recta hacia arriba.', 'No inclines el banco en exceso: el ejercicio se convierte en un press de hombros.', 'Desengancha y vuelve a enganchar la barra con los brazos extendidos, nunca con los codos doblados.']::text[], array['bb-press']::text[], true),
  ('incline-dumbbell-press', 'Dumbbell Bench Press (Incline)', 'Press de banca con mancuernas (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'dumbbell', 'push horizontal', 'compound', 'bilateral', array['Siéntate en el banco inclinado con las mancuernas sobre los muslos y súbelas con ayuda de las rodillas al tumbarte.', 'Mantén el pecho alto y las muñecas rectas, alineadas sobre los codos.', 'Baja las mancuernas a los lados de la parte alta del pecho y súbelas acercándolas ligeramente arriba.', 'No choques las mancuernas arriba ni pierdas tensión al final del recorrido.', 'Al terminar, lleva las mancuernas al pecho y siéntate con ellas sobre los muslos en vez de soltarlas a los lados.']::text[], '{}'::text[], true),
  ('inverted-row', 'Inverted Row', 'Remo invertido', 'Back', 'Upper Back', array['Upper Back']::text[], array['Lats', 'Rear Delts', 'Biceps']::text[], 'bodyweight', 'pull horizontal', 'compound', 'bilateral', array['Colócate bajo una barra fija a la altura de la cadera, agárrala en prono y extiende el cuerpo con talones apoyados.', 'Mantén el cuerpo recto como una tabla, con glúteos y abdomen contraídos.', 'Tira hasta que el pecho toque la barra juntando las escápulas y baja hasta estirar los brazos.', 'Evita que la cadera se hunda o que suba antes que el pecho en el tirón.', 'Comprueba que la barra del rack o la Smith esté bien trabada antes de colgarte.']::text[], '{}'::text[], true),
  ('kettlebell-row-single-arm', 'Kettlebell Row (Single-Arm)', 'Remo con kettlebell (a una mano)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps', 'Forearms']::text[], 'kettlebell', 'pull horizontal', 'compound', 'unilateral', array['Adopta una postura escalonada, apoya la mano libre en un banco o en el muslo y coge la kettlebell por el asa.', 'Mantén el torso inclinado y estable, con la cadera cuadrada al suelo.', 'Tira de la kettlebell hacia la cadera manteniendo la muñeca recta y bájala con control.', 'Evita que la kettlebell se balancee entre repeticiones; detén cada repetición abajo.', 'Agarra el asa con firmeza y asegúrate de tener espacio libre alrededor al remar.']::text[], '{}'::text[], true),
  ('kettlebell-swing', 'Kettlebell Swing', 'Swing con kettlebell', 'Full Body', 'Glutes', array['Glutes', 'Hamstrings']::text[], array['Lower Back', 'Abs', 'Forearms']::text[], 'kettlebell', 'hinge', 'compound', 'bilateral', array['Colócate con pies al ancho de los hombros y la kettlebell un paso delante de ti.', 'Mantén la espalda neutra y bisagra de cadera, no una sentadilla, en cada repetición.', 'Lanza la kettlebell entre las piernas y extiende la cadera con fuerza hasta la altura del pecho.', 'Evita subir la kettlebell con los brazos o hiperextender la espalda arriba.', 'Asegura espacio libre alrededor y deja la kettlebell en el suelo con control al terminar.']::text[], '{}'::text[], true),
  ('kettlebell-turkish-get-up', 'Kettlebell Turkish Get-Up', 'Levantamiento turco con kettlebell', 'Full Body', 'Abs', array['Abs', 'Front Delts']::text[], array['Obliques', 'Glutes', 'Triceps']::text[], 'kettlebell', 'core', 'compound', 'unilateral', array['Túmbate boca arriba con la kettlebell en una mano, brazo vertical y la rodilla del mismo lado flexionada.', 'Mantén el brazo bloqueado y la mirada en la kettlebell durante todo el levantamiento.', 'Sube por fases: codo, mano, puente, rodilla y de pie; deshaz los pasos en orden para bajar.', 'Evita apresurar las transiciones o dejar que el brazo se incline.', 'Practica primero sin peso o con un zapato encima del puño antes de cargar la kettlebell.']::text[], '{}'::text[], true),
  ('landmine-press', 'Landmine Press (Single Arm)', 'Press landmine (a una mano)', 'Shoulders', 'Front Delts', array['Front Delts', 'Upper Chest']::text[], array['Triceps', 'Abs']::text[], 'barbell', 'push vertical', 'compound', 'unilateral', array['Sujeta el extremo de la barra a la altura del hombro con una mano y el pie contrario adelantado.', 'Mantén el tronco firme y los hombros mirando al frente, sin girar.', 'Empuja la barra hacia arriba y adelante hasta extender el brazo y baja controlado al hombro.', 'No inclines el cuerpo hacia el lado contrario para empujar.', 'Asegura el extremo fijo de la barra en un soporte landmine o en una esquina estable.']::text[], '{}'::text[], true),
  ('lat-pulldown', 'Cable Lat Pulldown (Wide Grip)', 'Jalón al pecho en polea (agarre ancho)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps', 'Rear Delts']::text[], 'cable', 'pull vertical', 'compound', 'bilateral', array['Ajusta el rodillo sobre los muslos y agarra la barra en prono, más ancho que los hombros.', 'Inclina el torso unos grados hacia atrás con el pecho alto y la zona lumbar neutra.', 'Lleva la barra a la parte alta del pecho bajando los codos y sube controlando hasta estirar los dorsales.', 'Evita tirar la barra detrás de la nuca o balancear el torso hacia atrás para mover más peso.', 'Devuelve la barra arriba antes de levantarte para que las placas no caigan de golpe.']::text[], '{}'::text[], true),
  ('lateral-raises-machine', 'Machine Lateral Raise', 'Elevaciones laterales en máquina', 'Shoulders', 'Side Delts', array['Side Delts']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Ajusta el asiento para que el eje de la máquina quede alineado con tus hombros.', 'Apoya el pecho o la espalda en el soporte y mantén los hombros bajos.', 'Eleva los brazos hacia los lados hasta la altura de los hombros y baja lento.', 'No encojas los trapecios para subir más alto.', 'Elige un peso que puedas bajar con control, sin que las placas caigan de golpe.']::text[], '{}'::text[], true),
  ('leg-extensions-toes-dorsiflexed-neutral', 'Machine Leg Extension', 'Extensión de cuádriceps en máquina', 'Legs', 'Quads', array['Quads']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Alinea la rodilla con el eje de la máquina y apoya el rodillo justo encima del tobillo.', 'Mantén la espalda apoyada y sujeta las asas para que la cadera no se levante.', 'Extiende hasta arriba, aprieta un segundo y baja controlando la carga.', 'Evita lanzar el peso con impulso o dejar caer el rodillo de golpe.', 'Empieza con cargas moderadas si notas molestias en la rodilla y consulta a un profesional si duele.']::text[], array['leg-extensions-toes-dorsiflexed-out']::text[], true),
  ('leg-press-calf-raises-toes-neutral', 'Plate-Loaded Leg Press Calf Raise', 'Elevación de talones en prensa de discos', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'plate-loaded', 'isolation', 'isolation', 'bilateral', array['Siéntate en la prensa con solo la parte delantera de los pies en el borde inferior de la plataforma.', 'Mantén las rodillas casi extendidas y fijas durante toda la serie.', 'Empuja con las puntas hasta la extensión del tobillo y vuelve despacio al estiramiento.', 'Evita doblar las rodillas para empujar la plataforma con los cuádriceps.', 'Deja los seguros de la prensa puestos por si los pies resbalan del borde.']::text[], array['leg-press-calf-raises-neutral', 'calf']::text[], true),
  ('leg-press-quad-dominant', 'Plate-Loaded Leg Press', 'Prensa de piernas en máquina de discos', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Adductors']::text[], 'plate-loaded', 'squat', 'compound', 'bilateral', array['Siéntate con la espalda y la cadera pegadas al respaldo y los pies al ancho de cadera.', 'Mantén las rodillas alineadas con las puntas de los pies durante toda la bajada.', 'Baja la plataforma controlando hasta unos 90° de rodilla y empuja con todo el pie.', 'Evita que la cadera se despegue del asiento al final de la bajada.', 'No bloquees las rodillas arriba y suelta los seguros solo con la plataforma sujeta.']::text[], '{}'::text[], true),
  ('low-cable-ropes-curls', 'Cable Hammer Curl (Rope)', 'Curl martillo en polea (cuerda)', 'Arms', 'Biceps', array['Biceps', 'Forearms']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Coloca la polea abajo, sujeta la cuerda con palmas enfrentadas y da un paso atrás.', 'Mantén los codos pegados al torso y el cuerpo erguido sin inclinarte hacia atrás.', 'Sube la cuerda hasta el pecho separando ligeramente los extremos y baja con control.', 'Evita que el cable te arrastre los codos hacia delante en la bajada.', 'Mantén la tensión del cable al final y no sueltes la cuerda de golpe al terminar.']::text[], '{}'::text[], true),
  ('lying-leg-raise', 'Lying Leg Raise', 'Elevación de piernas tumbado', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Túmbate boca arriba con las piernas rectas y las manos bajo los glúteos o a los lados.', 'Mantén la zona lumbar en contacto con el suelo en todo momento.', 'Sube las piernas hasta la vertical y bájalas lentamente sin tocar el suelo.', 'Evita arquear la espalda al bajar las piernas cerca del suelo.', 'Flexiona un poco las rodillas si la zona lumbar se despega del suelo.']::text[], '{}'::text[], true),
  ('machine-assisted-pull-up', 'Machine Assisted Pull-Up', 'Dominadas asistidas en máquina', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'machine', 'pull vertical', 'compound', 'bilateral', array['Ajusta el contrapeso, apoya las rodillas o los pies en la plataforma y agarra las asas superiores.', 'Mantén el torso vertical y el pecho alto sin inclinarte hacia la plataforma.', 'Sube hasta que la barbilla pase las asas y baja despacio hasta extender los brazos por completo.', 'Evita usar tanta asistencia que la plataforma te impulse; reduce el contrapeso a medida que progresas.', 'Sube y baja de la plataforma con ambas manos agarradas para que no se mueva de golpe.']::text[], '{}'::text[], true),
  ('machine-chest-press-incline', 'Machine Chest Press (Incline)', 'Press de pecho en máquina (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'machine', 'push horizontal', 'compound', 'bilateral', array['Ajusta el asiento para que los agarres queden a la altura de la parte alta del pecho.', 'Apoya espalda y cabeza en el respaldo y mantén el pecho abierto.', 'Empuja hacia arriba y adelante sin bloquear los codos y vuelve lento a la posición inicial.', 'No eleves los hombros hacia las orejas al empujar.', 'Revisa que el asiento esté bien fijado antes de cargar peso.']::text[], '{}'::text[], true),
  ('machine-dip-assisted', 'Machine Dip (Assisted)', 'Fondos en máquina (asistidos)', 'Chest', 'Chest', array['Chest', 'Triceps']::text[], array['Front Delts']::text[], 'machine', 'push vertical', 'compound', 'bilateral', array['Elige el contrapeso, apoya las rodillas en la plataforma y sujeta las paralelas con brazos extendidos.', 'Mantén el torso ligeramente inclinado y los hombros bajos y atrás.', 'Baja controlado hasta que los codos formen unos 90° y empuja hasta extender los brazos.', 'Recuerda que más contrapeso significa más ayuda; no lo subas para ir más rápido.', 'Sube y baja de la plataforma con cuidado, siempre sujeto a los agarres.']::text[], '{}'::text[], true),
  ('machine-donkey-calf-raise', 'Machine Donkey Calf Raise', 'Elevación de talones tipo burro en máquina', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Inclínate con la cadera bajo la almohadilla y apoya los antebrazos en el soporte.', 'Mantén la espalda neutra y la cadera flexionada sin moverla durante la serie.', 'Baja los talones hasta un estiramiento profundo y sube hasta la punta de los pies.', 'Evita flexionar las rodillas para ayudarte a subir.', 'Ajusta la almohadilla a la cadera, nunca sobre la espalda baja.']::text[], '{}'::text[], true),
  ('machine-glute-kickback', 'Machine Glute Kickback', 'Patada de glúteo en máquina', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings']::text[], 'machine', 'isolation', 'isolation', 'unilateral', array['Apoya el pecho o los antebrazos en el soporte y coloca el pie en la plataforma o rodillo.', 'Mantén la espalda neutra y la cadera de apoyo fija al soporte.', 'Empuja hacia atrás hasta extender la cadera y vuelve despacio hasta notar estiramiento.', 'Evita rotar la cadera hacia afuera al final de la patada.', 'Ajusta la altura del apoyo para que la rodilla de trabajo no choque con la máquina.']::text[], '{}'::text[], true),
  ('machine-hip-abduction', 'Machine Hip Abduction', 'Abducción de cadera en máquina', 'Glutes', 'Abductors', array['Abductors', 'Glutes']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Siéntate con la espalda apoyada y las almohadillas por fuera de las rodillas.', 'Mantén la cadera pegada al asiento y el tronco quieto durante la apertura.', 'Abre las piernas hasta tu rango máximo, pausa y ciérralas sin que las placas choquen.', 'Evita balancear el tronco hacia delante y atrás para mover más peso.', 'Ajusta la apertura inicial a tu movilidad para no forzar la cadera.']::text[], '{}'::text[], true),
  ('machine-hip-adduction', 'Machine Hip Adduction', 'Aducción de cadera en máquina', 'Legs', 'Adductors', array['Adductors']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Siéntate con las almohadillas por dentro de las rodillas y elige una apertura cómoda.', 'Mantén la espalda apoyada y la pelvis estable en el asiento.', 'Cierra las piernas hasta juntar las almohadillas y ábrelas lento controlando el estiramiento.', 'Evita que las piernas se abran de golpe al final de cada repetición.', 'Empieza con una apertura reducida y amplíala poco a poco entre series.']::text[], '{}'::text[], true),
  ('machine-hip-thrust', 'Machine Hip Thrust', 'Hip thrust en máquina', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings', 'Quads']::text[], 'machine', 'hinge', 'compound', 'bilateral', array['Apoya la espalda en el respaldo y ajusta el cinturón o la almohadilla sobre la cadera.', 'Mantén los pies planos y las tibias verticales en la posición alta.', 'Eleva la cadera hasta la extensión completa, aprieta un segundo y desciende despacio.', 'Evita empujar con las puntas de los pies, que desplaza el trabajo a los cuádriceps.', 'Ajusta bien el cinturón antes de cargar para que no se mueva durante la serie.']::text[], '{}'::text[], true),
  ('machine-leg-extension-single-leg', 'Machine Leg Extension (Single-Leg)', 'Extensión de cuádriceps en máquina (a una pierna)', 'Legs', 'Quads', array['Quads']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'unilateral', array['Ajusta el respaldo y el rodillo como en la versión normal y apoya solo una pierna.', 'Mantén la pierna libre relajada y la cadera fija contra el asiento.', 'Extiende la rodilla por completo y vuelve despacio hasta casi tocar la pila.', 'Evita girar el tronco hacia el lado que trabaja para mover más peso.', 'Reduce la carga respecto a la versión bilateral para no sobrecargar la rodilla.']::text[], '{}'::text[], true),
  ('machine-preacher-curl', 'Machine Preacher Curl', 'Curl predicador en máquina', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Ajusta el asiento para que el codo quede alineado con el eje de giro de la máquina.', 'Mantén los brazos apoyados en el cojín y el pecho en contacto con el soporte.', 'Sube las asas hasta la contracción completa y baja en 2-3 segundos sin soltar la tensión.', 'Evita levantar la cadera del asiento para terminar las últimas repeticiones.', 'No dejes que la pila de peso golpee abajo; controla la extensión del codo.']::text[], '{}'::text[], true),
  ('machine-pullover', 'Machine Pullover', 'Pullover en máquina', 'Back', 'Lats', array['Lats']::text[], array['Triceps', 'Chest']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Ajusta el asiento para alinear los hombros con el eje de la máquina y apoya los codos en las almohadillas.', 'Mantén la espalda contra el respaldo y el cinturón ajustado si la máquina lo tiene.', 'Empuja con los codos hacia abajo en arco hasta los costados y vuelve despacio hasta estirar los dorsales.', 'Evita tirar con las manos; la presión debe hacerse con la parte trasera de los brazos.', 'Ajusta bien el eje de giro; una mala alineación carga el hombro en lugar del dorsal.']::text[], '{}'::text[], true),
  ('machine-reverse-hyperextension', 'Machine Reverse Hyperextension', 'Hiperextensión inversa en máquina', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings', 'Lower Back']::text[], 'machine', 'hinge', 'compound', 'bilateral', array['Túmbate boca abajo con la cadera en el borde del banco y los tobillos bajo el rodillo o la correa.', 'Mantén el tronco pegado al banco y sujeta las asas con firmeza.', 'Eleva las piernas hasta la línea del cuerpo con los glúteos y déjalas bajar controladas.', 'Evita balancear las piernas con impulso para subir más alto.', 'No pases de la horizontal al subir para no arquear en exceso la zona lumbar.']::text[], '{}'::text[], true),
  ('machine-seated-calf-raise', 'Machine Seated Calf Raise', 'Elevación de talones sentado en máquina', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Siéntate con la almohadilla sobre la parte baja de los muslos y las puntas en la plataforma.', 'Mantén el tronco erguido y las rodillas flexionadas a 90° en todo momento.', 'Baja los talones al máximo, pausa y sube hasta la contracción completa.', 'Evita impulsarte con el tronco o los brazos para mover la palanca.', 'Retira el seguro solo con la almohadilla bien ajustada sobre los muslos.']::text[], '{}'::text[], true),
  ('machine-seated-leg-curl-single-leg', 'Machine Seated Leg Curl (Single-Leg)', 'Curl femoral sentado en máquina (a una pierna)', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Calves']::text[], 'machine', 'isolation', 'isolation', 'unilateral', array['Ajusta la máquina como en la versión bilateral y coloca solo una pierna sobre el rodillo.', 'Mantén ambos muslos sujetos por el rodillo superior y la cadera quieta.', 'Flexiona la rodilla al máximo, pausa breve y regresa lento hasta casi extender.', 'Evita rotar la pierna hacia fuera o hacia dentro para ayudarte.', 'Elige una carga menor y compensa con más control en la fase de bajada.']::text[], '{}'::text[], true),
  ('machine-seated-leg-press', 'Machine Seated Leg Press', 'Prensa de piernas sentado en máquina', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Adductors']::text[], 'machine', 'squat', 'compound', 'bilateral', array['Ajusta el asiento para empezar con las rodillas a unos 90° y los pies planos en la plataforma.', 'Mantén la espalda apoyada y sujeta las asas laterales para estabilizarte.', 'Empuja de forma fluida hasta casi extender y regresa sin dejar caer las placas.', 'Evita acercar tanto el asiento que la cadera se enrolle en la posición inicial.', 'No bloquees las rodillas arriba y deja la pila de placas apoyada al terminar.']::text[], '{}'::text[], true),
  ('machine-standing-leg-curl', 'Machine Standing Leg Curl', 'Curl femoral de pie en máquina', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Calves']::text[], 'machine', 'isolation', 'isolation', 'unilateral', array['Apoya el muslo en la almohadilla y coloca el rodillo detrás del tobillo de la pierna que trabaja.', 'Mantén la cadera pegada al soporte y el tronco quieto sujetando las asas.', 'Lleva el talón hacia el glúteo y baja despacio sin dejar que la carga caiga.', 'Evita arquear la espalda baja para subir el talón más alto.', 'Ajusta la altura del soporte para que la rodilla quede alineada con el eje.']::text[], '{}'::text[], true),
  ('machine-triceps-extension', 'Machine Triceps Extension', 'Extensión de tríceps en máquina', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Ajusta el asiento para alinear los codos con el eje de la máquina y apoya los brazos en el cojín.', 'Mantén la espalda contra el respaldo y los hombros abajo durante toda la serie.', 'Extiende los codos hasta abajo, aprieta el tríceps y vuelve despacio a la flexión.', 'Evita levantar los codos del cojín para empujar con los hombros.', 'No dejes que la pila de peso golpee al volver; controla toda la fase excéntrica.']::text[], '{}'::text[], true),
  ('mid-cable-fly', 'Cable Fly (Mid Height)', 'Aperturas en polea (altura media)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts']::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Coloca las poleas a la altura del pecho y da un paso adelante con un pie delante del otro.', 'Mantén un ligero ángulo fijo en los codos y el torso estable, sin balancearte.', 'Junta las manos delante del pecho en un arco amplio y vuelve controlado hasta notar estiramiento.', 'No conviertas la apertura en un press doblando y estirando los codos.', 'No lleves los brazos más atrás de la línea del cuerpo si notas tensión en el hombro.']::text[], '{}'::text[], true),
  ('mountain-climber', 'Mountain Climber', 'Escaladores', 'Core', 'Abs', array['Abs', 'Hip Flexors']::text[], array['Front Delts', 'Quads']::text[], 'bodyweight', 'core', 'compound', 'bilateral', array['Colócate en plancha alta con las manos bajo los hombros y el cuerpo en línea recta.', 'Mantén la cadera baja y estable mientras alternas las piernas.', 'Lleva una rodilla hacia el pecho y cambia de pierna con ritmo constante.', 'Evita subir la cadera hacia el techo cuando aumentas la velocidad.', 'Reduce el ritmo si notas que los hombros pierden la posición sobre las manos.']::text[], '{}'::text[], true),
  ('neutral-grip-lat-pulldown', 'Cable Lat Pulldown (Neutral Grip)', 'Jalón al pecho en polea (agarre neutro)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'cable', 'pull vertical', 'compound', 'bilateral', array['Engancha el maneral de agarre neutro, siéntate con los muslos bajo el rodillo y los brazos estirados.', 'Mantén el pecho alto y los codos cerca del cuerpo, apuntando hacia el suelo.', 'Tira del maneral hasta el esternón llevando los codos a los costados y sube lento hasta extender.', 'Evita redondear la espalda al final del tirón para acercar el maneral al pecho.', 'Comprueba que el mosquetón del maneral esté bien cerrado antes de cargar la polea.']::text[], '{}'::text[], true),
  ('neutral-grip-pin-loaded-shoulder-press', 'Machine Shoulder Press (Neutral Grip)', 'Press de hombros en máquina (agarre neutro)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'machine', 'push vertical', 'compound', 'bilateral', array['Ajusta el asiento para que los agarres neutros queden a la altura de los hombros.', 'Apoya la espalda y la cabeza y mantén los codos ligeramente por delante del cuerpo.', 'Empuja hacia arriba sin bloquear los codos y baja despacio hasta la altura de los hombros.', 'No dejes que la pila de placas descanse entre repeticiones.', 'Comprueba la altura del asiento: si empiezas demasiado bajo, el hombro trabaja forzado.']::text[], '{}'::text[], true),
  ('neutral-grip-supp-rows', 'Machine Chest-Supported Row (Neutral Grip)', 'Remo con apoyo de pecho en máquina (agarre neutro)', 'Back', 'Upper Back', array['Upper Back']::text[], array['Lats', 'Biceps', 'Rear Delts']::text[], 'machine', 'pull horizontal', 'compound', 'bilateral', array['Siéntate con el pecho contra el cojín y agarra las asas verticales con las palmas enfrentadas.', 'Mantén la espalda neutra y los codos cerca del cuerpo durante todo el remo.', 'Tira de las asas hasta que los codos queden detrás del torso y estira los brazos sin soltar la tensión.', 'Evita encoger los hombros o adelantar la cabeza al final del tirón.', 'Deja que el peso vuelva a su sitio de forma controlada al terminar la serie.']::text[], '{}'::text[], true),
  ('neutral-grip-weighted-chin-ups', 'Pull-Up (Neutral Grip)', 'Dominadas (agarre neutro)', 'Back', 'Lats', array['Lats']::text[], array['Biceps', 'Upper Back', 'Forearms']::text[], 'bodyweight', 'pull vertical', 'compound', 'bilateral', array['Cuélgate de los agarres paralelos con las palmas enfrentadas y los brazos extendidos.', 'Mantén las costillas abajo y una ligera inclinación del torso hacia atrás durante la subida.', 'Sube llevando los codos pegados al cuerpo hasta que la barbilla supere los agarres y baja sin prisa.', 'Evita encoger los hombros al inicio; deprime las escápulas antes de flexionar los codos.', 'Si usas lastre, asegura bien el cinturón o la mancuerna para que no se balancee entre las piernas.']::text[], '{}'::text[], true),
  ('nordic-hamstring-curl', 'Nordic Hamstring Curl', 'Curl nórdico de isquiotibiales', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Glutes', 'Calves']::text[], 'bodyweight', 'isolation', 'isolation', 'bilateral', array['Arrodíllate sobre una colchoneta con los tobillos bien fijados bajo un soporte o por un compañero.', 'Mantén una línea recta de rodillas a cabeza, con glúteos y abdomen contraídos.', 'Déjate caer hacia delante lo más lento posible y vuelve ayudándote con las manos si hace falta.', 'Evita doblar la cadera para acortar la palanca durante la bajada.', 'Coloca las manos listas para frenar la caída y progresa el rango poco a poco.']::text[], '{}'::text[], true),
  ('pec-deck-fly', 'Pec Deck Fly', 'Aperturas en máquina (pec deck)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Ajusta el asiento para que los agarres queden a la altura del pecho con los codos casi extendidos.', 'Mantén la espalda apoyada y las escápulas juntas durante toda la serie.', 'Junta los agarres delante del pecho, aprieta un segundo y abre con control.', 'Evita que los brazos se vayan muy atrás en la apertura con mucho peso.', 'Regula el tope de recorrido de la máquina para limitar la apertura si lo necesitas.']::text[], '{}'::text[], true),
  ('plank', 'Plank', 'Plancha', 'Core', 'Abs', array['Abs']::text[], array['Obliques', 'Front Delts', 'Glutes']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Apoya los antebrazos con los codos bajo los hombros y extiende las piernas sobre las puntas.', 'Mantén una línea recta de la cabeza a los talones con los glúteos apretados.', 'Sostén la posición respirando de forma continua y empujando el suelo con los antebrazos.', 'Evita que la cadera se hunda o suba demasiado hacia el techo.', 'Termina la serie cuando pierdas la alineación, aunque no hayas llegado al tiempo.']::text[], '{}'::text[], true),
  ('plate-loaded-belt-squat', 'Plate-Loaded Belt Squat', 'Sentadilla con cinturón en máquina de discos', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'plate-loaded', 'squat', 'compound', 'bilateral', array['Ajusta el cinturón a la cadera y coloca los pies en la plataforma al ancho de hombros.', 'Mantén el torso erguido y sujeta las asas solo para equilibrarte, sin tirar de ellas.', 'Baja en vertical hasta la profundidad deseada y sube extendiendo cadera y rodillas a la vez.', 'Evita que el cinturón se suba a la cintura, debe quedar sobre la cadera.', 'Revisa que la cadena y el mosquetón estén bien cerrados antes de cargar peso.']::text[], '{}'::text[], true),
  ('plate-loaded-chest-press-incline', 'Plate-Loaded Chest Press (Incline)', 'Press de pecho en máquina de discos (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'plate-loaded', 'push horizontal', 'compound', 'bilateral', array['Siéntate con los agarres a la altura de la parte alta del pecho y los pies apoyados.', 'Mantén las escápulas juntas y la espalda pegada al respaldo.', 'Empuja los brazos de la máquina hacia arriba y desciende con control hasta notar estiramiento.', 'Evita bajar tan rápido que los discos golpeen al final del recorrido.', 'Retira los discos por igual de ambos lados para que la máquina no se desequilibre.']::text[], '{}'::text[], true),
  ('plate-loaded-chest-press-wide-grip', 'Plate-Loaded Chest Press (Wide Grip)', 'Press de pecho en máquina de discos (agarre ancho)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts', 'Triceps']::text[], 'plate-loaded', 'push horizontal', 'compound', 'bilateral', array['Ajusta el asiento para que los agarres anchos queden a la altura de la mitad del pecho.', 'Mantén la espalda y la cabeza apoyadas y las escápulas juntas contra el respaldo.', 'Empuja los agarres hacia delante sin bloquear los codos y vuelve despacio hasta notar estiramiento.', 'No despegues los hombros del respaldo al final del empuje.', 'Carga y descarga los discos de forma equilibrada en ambos lados de la máquina.']::text[], '{}'::text[], true),
  ('plate-loaded-high-row', 'Plate-Loaded High Row', 'Remo alto en máquina de discos', 'Back', 'Lats', array['Lats', 'Upper Back']::text[], array['Rear Delts', 'Biceps']::text[], 'plate-loaded', 'pull vertical', 'compound', 'bilateral', array['Fija los muslos bajo el rodillo y agarra las asas altas con los brazos estirados por encima de la cabeza.', 'Mantén el pecho alto y una ligera inclinación del torso hacia delante, sin arquear la zona lumbar.', 'Tira de las asas hacia abajo y atrás hasta los costados del pecho y vuelve controlando hasta arriba.', 'Evita dejar que el peso te levante del asiento en la fase de subida.', 'Ajusta el rodillo de los muslos para quedar bien sujeto antes de cargar discos pesados.']::text[], '{}'::text[], true),
  ('plate-loaded-lat-pulldown', 'Plate-Loaded Lat Pulldown', 'Jalón al pecho en máquina de discos', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps', 'Rear Delts']::text[], 'plate-loaded', 'pull vertical', 'compound', 'bilateral', array['Carga los discos por igual en ambos lados, fija los muslos bajo el rodillo y agarra las asas.', 'Mantén el pecho alto y el torso quieto durante todo el recorrido.', 'Tira de las asas hacia los costados del pecho y deja que suban despacio hasta estirar los brazos.', 'Evita soltar las asas de golpe arriba; controla la fase excéntrica en cada repetición.', 'Coloca y retira los discos con la máquina en reposo y alterna los lados para no desequilibrarla.']::text[], '{}'::text[], true),
  ('plate-loaded-leg-press-single-leg', 'Plate-Loaded Leg Press (Single-Leg)', 'Prensa de piernas en máquina de discos (a una pierna)', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'plate-loaded', 'squat', 'compound', 'unilateral', array['Coloca un pie en el centro de la plataforma y apoya el otro en el suelo o el marco.', 'Mantén la pelvis nivelada y la rodilla de trabajo en línea con el segundo dedo del pie.', 'Baja despacio hasta donde la cadera siga apoyada y empuja hasta casi extender.', 'Evita que la rodilla se vaya hacia dentro al empujar.', 'Empieza con poca carga y mantén los seguros cerca hasta dominar el equilibrio.']::text[], '{}'::text[], true),
  ('plate-loaded-low-row', 'Plate-Loaded Low Row', 'Remo bajo en máquina de discos', 'Back', 'Lats', array['Lats', 'Upper Back']::text[], array['Biceps', 'Rear Delts']::text[], 'plate-loaded', 'pull horizontal', 'compound', 'bilateral', array['Ajusta el asiento para que el pecho quede contra el cojín y agarra las asas bajas con brazos estirados.', 'Mantén el pecho apoyado y el torso erguido sin inclinarte hacia atrás.', 'Tira de las asas hacia las caderas llevando los codos atrás y vuelve hasta estirar la espalda.', 'Evita acortar el recorrido; deja que las escápulas se separen en cada estiramiento.', 'Carga los discos de forma equilibrada y retíralos al acabar para dejar la máquina segura.']::text[], '{}'::text[], true),
  ('plate-loaded-pendulum-squat', 'Plate-Loaded Pendulum Squat', 'Sentadilla péndulo en máquina de discos', 'Legs', 'Quads', array['Quads']::text[], array['Glutes', 'Adductors']::text[], 'plate-loaded', 'squat', 'compound', 'bilateral', array['Apoya la espalda y los hombros en las almohadillas con los pies en el centro de la plataforma.', 'Mantén la espalda baja pegada al respaldo durante todo el arco del movimiento.', 'Baja profundo dejando que las rodillas avancen y sube sin bloquear del todo arriba.', 'Evita despegar los talones de la plataforma en la parte baja.', 'Usa el seguro de la máquina al entrar y salir para no quedar atrapado bajo la carga.']::text[], '{}'::text[], true),
  ('plate-loaded-t-bar-row-chest-supported', 'Plate-Loaded T-Bar Row (Chest-Supported)', 'Remo en T en máquina de discos (con apoyo de pecho)', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps']::text[], 'plate-loaded', 'pull horizontal', 'compound', 'bilateral', array['Sube a la plataforma, apoya el pecho en el cojín y agarra las asas con los brazos estirados.', 'Mantén el pecho pegado al cojín y el cuello neutro sin levantar la cabeza.', 'Tira de las asas hacia el torso juntando las escápulas y baja la carga con control.', 'Evita despegar el pecho del cojín para empujar con las piernas al final del tirón.', 'Sube y baja de la plataforma con la carga apoyada en su posición de reposo.']::text[], '{}'::text[], true),
  ('plate-loaded-wide-grip-shoulder-press-machine', 'Plate-Loaded Shoulder Press (Wide Grip)', 'Press de hombros en máquina de discos (agarre ancho)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'plate-loaded', 'push vertical', 'compound', 'bilateral', array['Ajusta el asiento para empezar con los agarres anchos justo por encima de los hombros.', 'Mantén la espalda y la cabeza apoyadas y el abdomen activo.', 'Empuja los brazos de la máquina hacia arriba y baja despacio hasta notar el hombro estirado.', 'No arquees la espalda baja para terminar las últimas repeticiones.', 'Carga los discos igual en ambos lados y retíralos al terminar.']::text[], '{}'::text[], true),
  ('prone-leg-curl-toes-dorsiflexed-neutral', 'Machine Lying Leg Curl', 'Curl femoral tumbado en máquina', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Calves']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Túmbate boca abajo con las rodillas justo fuera del banco y el rodillo sobre los talones.', 'Mantén la cadera pegada al banco y sujeta las asas durante todo el recorrido.', 'Flexiona las rodillas llevando los talones hacia los glúteos y baja en dos o tres segundos.', 'Evita levantar la cadera del banco para completar la repetición.', 'No dejes que la carga extienda las rodillas de golpe al final de la bajada.']::text[], array['prone-leg-curls-toes-dorsiflexed-neutral', 'leg-curl']::text[], true),
  ('pull-up', 'Pull-Up', 'Dominadas', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps', 'Forearms']::text[], 'bodyweight', 'pull vertical', 'compound', 'bilateral', array['Cuélgate de la barra con agarre prono algo más ancho que los hombros y los brazos totalmente extendidos.', 'Mantén el pecho alto y las piernas juntas, con el abdomen firme para no balancearte.', 'Inicia bajando las escápulas y sube hasta pasar la barbilla sobre la barra; baja controlado hasta extender.', 'Evita el impulso con las piernas (kipping) y los medios recorridos que dejan los codos flexionados.', 'Baja de la barra con control al terminar la serie, sin soltarte de golpe desde arriba.']::text[], '{}'::text[], true),
  ('pull-up-wide-grip', 'Pull-Up (Wide Grip)', 'Dominadas (agarre ancho)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Rear Delts', 'Biceps']::text[], 'bodyweight', 'pull vertical', 'compound', 'bilateral', array['Agarra la barra en prono a unos 1,5 anchos de hombros y cuélgate con los brazos extendidos.', 'Saca el pecho hacia la barra y mantén los codos apuntando hacia los lados y abajo.', 'Tira de los codos hacia las costillas hasta acercar el pecho alto a la barra y baja en 2-3 segundos.', 'Evita abrir tanto el agarre que pierdas recorrido o que los hombros se suban hacia las orejas.', 'Elige un ancho que te permita completar el recorrido sin molestias en los hombros.']::text[], '{}'::text[], true),
  ('push-up', 'Push-Up', 'Flexiones', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts', 'Abs']::text[], 'bodyweight', 'push horizontal', 'compound', 'bilateral', array['Apoya las manos algo más anchas que los hombros y extiende las piernas en plancha.', 'Mantén una línea recta de cabeza a talones apretando glúteos y abdomen.', 'Baja el pecho casi hasta el suelo y empuja hasta extender los brazos.', 'No dejes caer la cadera ni la saques hacia arriba.', 'Si pierdes la línea del cuerpo, apoya las rodillas o eleva las manos para terminar la serie.']::text[], '{}'::text[], true),
  ('push-up-close-grip', 'Push-Up (Close Grip)', 'Flexiones (agarre cerrado)', 'Chest', 'Triceps', array['Triceps', 'Chest']::text[], array['Front Delts']::text[], 'bodyweight', 'push horizontal', 'compound', 'bilateral', array['Coloca las manos bajo los hombros o un poco más juntas, con los dedos hacia delante.', 'Mantén los codos pegados a las costillas y el cuerpo en línea recta.', 'Baja hasta que el pecho roce las manos y empuja extendiendo los codos.', 'Evita que los codos se abran hacia los lados al bajar.', 'Si notas las muñecas cargadas, separa un poco las manos o usa agarres de flexiones.']::text[], '{}'::text[], true),
  ('push-up-decline', 'Push-Up (Decline)', 'Flexiones (declinadas)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Triceps', 'Front Delts', 'Abs']::text[], 'bodyweight', 'push horizontal', 'compound', 'bilateral', array['Apoya los pies en un banco y las manos en el suelo algo más anchas que los hombros.', 'Aprieta el abdomen para que la zona lumbar no se hunda.', 'Baja la cara y el pecho hacia el suelo de forma controlada y empuja hacia arriba.', 'No eleves la cadera para acortar el recorrido.', 'Empieza con los pies a poca altura y súbelos solo cuando controles la técnica.']::text[], '{}'::text[], true),
  ('push-up-incline', 'Push-Up (Incline)', 'Flexiones (inclinadas)', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'bodyweight', 'push horizontal', 'compound', 'bilateral', array['Apoya las manos en un banco o caja estable, algo más anchas que los hombros.', 'Mantén el cuerpo recto como una tabla, con el abdomen activo.', 'Lleva el pecho hacia el borde del banco y empuja hasta extender los brazos.', 'Evita adelantar la cabeza hacia el banco antes que el pecho.', 'Comprueba que el banco o la caja no se deslice antes de apoyarte.']::text[], '{}'::text[], true),
  ('push-up-pike', 'Push-Up (Pike)', 'Flexiones (en pica)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Triceps', 'Upper Chest']::text[], 'bodyweight', 'push vertical', 'compound', 'bilateral', array['Apoya manos y pies en el suelo y eleva la cadera formando una V invertida.', 'Mantén la cadera alta y la espalda recta durante todo el movimiento.', 'Baja la cabeza hacia el suelo entre las manos y empuja hasta extender los brazos.', 'Evita bajar la cadera y convertirlo en una flexión normal.', 'Desciende despacio y no apoyes peso sobre la cabeza al llegar abajo.']::text[], '{}'::text[], true),
  ('reverse-grip-chin-up-weighted', 'Chin-Up', 'Dominadas supinas', 'Back', 'Lats', array['Lats', 'Biceps']::text[], array['Upper Back', 'Forearms']::text[], 'bodyweight', 'pull vertical', 'compound', 'bilateral', array['Agarra la barra con las palmas hacia ti, a la anchura de los hombros, y cuélgate con brazos extendidos.', 'Mantén el torso estable y los codos por delante del cuerpo, apuntando al suelo.', 'Tira hasta llevar la barbilla sobre la barra apretando los dorsales y baja hasta extender por completo.', 'Evita quedarte a medio camino en la bajada; extender del todo trabaja el dorsal en estiramiento.', 'Si añades lastre, súbelo de forma progresiva y mantén la técnica limpia en todas las repeticiones.']::text[], array['chin']::text[], true),
  ('reverse-grip-lats-machine', 'Machine Lat Pulldown (Underhand Grip)', 'Jalón en máquina (agarre supino)', 'Back', 'Lats', array['Lats']::text[], array['Biceps', 'Upper Back']::text[], 'machine', 'pull vertical', 'compound', 'bilateral', array['Ajusta el asiento para que los agarres queden a tu alcance con los brazos extendidos y palmas hacia ti.', 'Apoya bien el pecho o los muslos según la máquina y mantén la espalda neutra.', 'Lleva los agarres hacia abajo y atrás siguiendo el arco de la máquina y sube lento hasta estirar.', 'Evita despegarte del asiento o del apoyo para ganar recorrido con impulso.', 'Verifica que el pasador del peso esté bien introducido antes de empezar.']::text[], '{}'::text[], true),
  ('reverse-pec-deck-fly', 'Reverse Pec Deck Fly', 'Aperturas inversas en máquina (pec deck)', 'Shoulders', 'Rear Delts', array['Rear Delts']::text[], array['Upper Back']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Siéntate de cara al respaldo con los agarres a la altura de los hombros.', 'Mantén el pecho apoyado y los hombros bajos durante toda la serie.', 'Abre los brazos hacia atrás en arco hasta la línea del cuerpo y vuelve controlado.', 'No tires con los trapecios encogiendo los hombros.', 'Ajusta los brazos de la máquina a la posición inversa antes de sentarte.']::text[], '{}'::text[], true),
  ('romanian-deadlift', 'Barbell Romanian Deadlift', 'Peso muerto rumano con barra', 'Legs', 'Hamstrings', array['Hamstrings', 'Glutes']::text[], array['Lower Back', 'Forearms']::text[], 'barbell', 'hinge', 'compound', 'bilateral', array['Empieza de pie con la barra a la altura de la cadera y agarre por fuera de los muslos.', 'Mantén las rodillas ligeramente flexionadas y fijas, con la espalda neutra.', 'Lleva la cadera atrás deslizando la barra por las piernas hasta notar el estiramiento y sube.', 'Evita convertirlo en sentadilla doblando más las rodillas al bajar.', 'Baja solo hasta donde puedas mantener la espalda neutra, aunque no llegues a media tibia.']::text[], array['bb-rdl']::text[], true),
  ('rope-low-cable-oh-tricep-extensions', 'Cable Overhead Triceps Extension (Rope)', 'Extensión de tríceps sobre la cabeza en polea (cuerda)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Ponte de espaldas a la polea, sujeta la cuerda detrás de la cabeza y adelanta un pie.', 'Mantén los codos apuntando al frente y cerca de la cabeza durante toda la serie.', 'Extiende los codos hacia arriba y adelante, y vuelve lento hasta sentir el estiramiento.', 'Evita abrir los codos hacia los lados o arquear la zona lumbar.', 'Activa el abdomen para proteger la espalda baja mientras el cable tira hacia atrás.']::text[], '{}'::text[], true),
  ('russian-twist', 'Russian Twist', 'Giro ruso', 'Core', 'Obliques', array['Obliques']::text[], array['Abs', 'Hip Flexors']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Siéntate con rodillas flexionadas, inclina el tronco atrás y junta las manos frente al pecho.', 'Mantén la espalda larga y el pecho alto, sin encorvarte.', 'Gira el tronco a un lado y al otro llevando las manos junto a la cadera con control.', 'Evita mover solo los brazos; el giro debe salir de las costillas.', 'Apoya los talones en el suelo si al elevar los pies pierdes la postura de la espalda.']::text[], '{}'::text[], true),
  ('seated-cable-row', 'Cable Seated Row', 'Remo sentado en polea', 'Back', 'Upper Back', array['Upper Back']::text[], array['Lats', 'Biceps', 'Rear Delts']::text[], 'cable', 'pull horizontal', 'compound', 'bilateral', array['Siéntate con los pies en el apoyo, las rodillas algo flexionadas y el maneral en V con brazos estirados.', 'Mantén el torso erguido y quieto, con el pecho alto y los hombros lejos de las orejas.', 'Lleva el maneral al abdomen juntando las escápulas y estira los brazos dejando que avancen los hombros.', 'Evita balancear el torso adelante y atrás para mover el peso con la zona lumbar.', 'Agarra y suelta el maneral con las rodillas flexionadas para no tirar de la espalda baja.']::text[], '{}'::text[], true),
  ('seated-leg-curl-toes-dorsiflexed-neutral', 'Machine Seated Leg Curl', 'Curl femoral sentado en máquina', 'Legs', 'Hamstrings', array['Hamstrings']::text[], array['Calves']::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Ajusta el respaldo para alinear la rodilla con el eje y baja el rodillo sobre los muslos.', 'Mantén la espalda apoyada y el tronco algo inclinado adelante para estirar más los isquios.', 'Flexiona hasta llevar los talones bajo el asiento y vuelve despacio hasta casi extender.', 'Evita dejar el rodillo de muslos suelto, porque la cadera se levantará.', 'Ajusta bien el rodillo inferior sobre el tobillo para que no se deslice a la pantorrilla.']::text[], array['seated-leg-curls-toes-dorsiflexed-neutral', 'seated-leg-curls-toes-dorsiflexed-out']::text[], true),
  ('side-plank', 'Side Plank', 'Plancha lateral', 'Core', 'Obliques', array['Obliques']::text[], array['Abs', 'Glutes', 'Abductors']::text[], 'bodyweight', 'core', 'isolation', 'unilateral', array['Túmbate de lado con el codo bajo el hombro y los pies apilados o uno delante del otro.', 'Mantén cadera, hombros y tobillos alineados en una línea recta.', 'Eleva la cadera del suelo y sostén la posición sin rotar el tronco.', 'Evita dejar caer la cadera o llevarla hacia atrás.', 'Apoya la rodilla de abajo si no puedes mantener la línea con las piernas extendidas.']::text[], '{}'::text[], true),
  ('single-arm-lat-pulldown', 'Cable Lat Pulldown (Single-Arm)', 'Jalón al pecho en polea (a una mano)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'cable', 'pull vertical', 'compound', 'unilateral', array['Siéntate bajo la polea alta con un agarre individual y el brazo totalmente estirado arriba.', 'Mantén el torso de frente y estable, sin girarte hacia el lado que trabaja.', 'Baja el codo hacia la cadera siguiendo una línea en diagonal y deja que el brazo suba estirando el dorsal.', 'Evita compensar inclinándote de lado; el movimiento debe venir del hombro y el codo.', 'Empieza con el brazo menos fuerte y haz las mismas repeticiones con el otro.']::text[], '{}'::text[], true),
  ('single-db-preacher-curls', 'Dumbbell Preacher Curl (Single-Arm)', 'Curl predicador con mancuerna (a una mano)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'unilateral', array['Apoya el tríceps entero en el cojín con la axila sobre el borde y la mancuerna en supinación.', 'Mantén el hombro bajo y el torso quieto; la mano libre puede sujetar el cojín para estabilizarte.', 'Flexiona el codo hasta arriba sin despegar el brazo y baja despacio hasta casi la extensión.', 'Evita girar el torso o rotar la muñeca hacia dentro para terminar la repetición.', 'Usa un peso que puedas frenar abajo; un rebote en extensión completa carga mucho el codo.']::text[], '{}'::text[], true),
  ('single-hand-cable-unilateral-rows', 'Cable Seated Row (Single-Arm)', 'Remo sentado en polea (a una mano)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'cable', 'pull horizontal', 'compound', 'unilateral', array['Siéntate frente a la polea con un agarre individual y el brazo estirado hacia delante.', 'Mantén los hombros alineados y el torso estable, permitiendo solo una rotación leve.', 'Tira del agarre hacia la cadera llevando el codo atrás y extiende el brazo dejando que el hombro avance.', 'Evita girar todo el torso para completar la repetición; la fuerza debe venir de la espalda.', 'Empieza por el lado más débil y apoya la mano libre en el muslo para estabilizarte.']::text[], '{}'::text[], true),
  ('smith-machine-bench-press', 'Smith Machine Bench Press', 'Press de banca en máquina Smith', 'Chest', 'Chest', array['Chest']::text[], array['Triceps', 'Front Delts']::text[], 'smith-machine', 'push horizontal', 'compound', 'bilateral', array['Coloca el banco para que la barra baje justo a la parte baja del pecho.', 'Junta las escápulas y planta los pies firmes en el suelo.', 'Desbloquea girando la barra, baja controlado al pecho y empuja recto hacia arriba.', 'No coloques el banco demasiado atrás o adelante: la barra debe caer sobre el pecho, no el cuello.', 'Ajusta los topes de la Smith justo por encima del pecho antes de empezar.']::text[], '{}'::text[], true),
  ('smith-machine-bench-press-incline', 'Smith Machine Bench Press (Incline)', 'Press de banca en máquina Smith (inclinado)', 'Chest', 'Upper Chest', array['Upper Chest']::text[], array['Front Delts', 'Triceps']::text[], 'smith-machine', 'push horizontal', 'compound', 'bilateral', array['Sitúa el banco inclinado de forma que la barra baje a la parte alta del pecho.', 'Mantén las escápulas retraídas y los glúteos apoyados en el asiento.', 'Baja la barra hasta rozar el pecho bajo las clavículas y empuja de forma constante.', 'Evita despegar la espalda del banco para mover más peso.', 'Gira los ganchos para bloquear la barra en cuanto termines la última repetición.']::text[], '{}'::text[], true),
  ('smith-machine-bent-over-row', 'Smith Machine Bent-Over Row', 'Remo inclinado en máquina Smith', 'Back', 'Upper Back', array['Upper Back', 'Lats']::text[], array['Rear Delts', 'Biceps']::text[], 'smith-machine', 'pull horizontal', 'compound', 'bilateral', array['Ajusta los topes a la altura de las rodillas, agarra la barra en prono e inclina el torso desde la cadera.', 'Colócate de modo que la barra suba en línea recta hacia tu abdomen sin chocar con los muslos.', 'Tira la barra al ombligo apretando las escápulas y bájala controlando hasta estirar los brazos.', 'Evita quedarte demasiado cerca o lejos de la barra; la guía fija obliga a ajustar bien la posición.', 'Gira la barra para engancharla en los ganchos al terminar antes de soltarla.']::text[], '{}'::text[], true),
  ('smith-machine-calf-raise', 'Smith Machine Calf Raise', 'Elevación de talones en máquina Smith', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'smith-machine', 'isolation', 'isolation', 'bilateral', array['Coloca un step bajo la barra y apoya la parte delantera de los pies en su borde.', 'Mantén el cuerpo vertical bajo la barra y las rodillas casi extendidas.', 'Sube a la punta de los pies, mantén un segundo y baja hasta el estiramiento.', 'Evita acortar el recorrido quedándote solo en la mitad alta.', 'Comprueba que el step no se desplace y ajusta los topes de la Smith.']::text[], '{}'::text[], true),
  ('smith-machine-hip-thrust', 'Smith Machine Hip Thrust', 'Hip thrust en máquina Smith', 'Glutes', 'Glutes', array['Glutes']::text[], array['Hamstrings', 'Quads']::text[], 'smith-machine', 'hinge', 'compound', 'bilateral', array['Coloca un banco perpendicular a la Smith y sitúa la barra acolchada sobre el pliegue de la cadera.', 'Mantén la mirada al frente y el tronco rígido al subir y bajar.', 'Sube la cadera hasta alinearla con hombros y rodillas y baja hasta casi tocar el suelo.', 'Evita colocar los pies tan lejos que los isquios dominen el movimiento.', 'Gira la barra para desengancharla solo cuando estés bien colocado debajo.']::text[], '{}'::text[], true),
  ('smith-machine-shoulder-press', 'Smith Machine Shoulder Press (Seated)', 'Press de hombros en máquina Smith (sentado)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'smith-machine', 'push vertical', 'compound', 'bilateral', array['Coloca el banco vertical para que la barra baje justo por delante de tu cara.', 'Mantén la espalda apoyada y las muñecas rectas sobre los codos.', 'Desbloquea la barra, bájala hasta la barbilla y empuja hasta arriba sin bloquear.', 'Evita adelantar la cabeza hacia la barra al bajar.', 'Fija los topes de seguridad de la Smith a la altura de los hombros.']::text[], '{}'::text[], true),
  ('smith-machine-shrug', 'Smith Machine Shrug', 'Encogimientos en máquina Smith', 'Back', 'Traps', array['Traps']::text[], array['Upper Back', 'Forearms']::text[], 'smith-machine', 'isolation', 'isolation', 'bilateral', array['Ajusta los topes a media altura del muslo, agarra la barra en prono y desengánchala girando las muñecas.', 'Mantén el cuerpo pegado a la barra y la espalda recta durante todo el movimiento.', 'Eleva los hombros siguiendo la guía de la barra, aprieta arriba y baja con un recorrido completo.', 'Evita acortar el recorrido con cargas excesivas; la amplitud importa más que el peso.', 'Coloca los topes de seguridad justo bajo la posición inicial antes de empezar.']::text[], '{}'::text[], true),
  ('smith-machine-split-squat', 'Smith Machine Split Squat', 'Sentadilla dividida en máquina Smith', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'smith-machine', 'lunge', 'compound', 'unilateral', array['Colócate bajo la barra en posición de zancada con el pie delantero algo adelantado.', 'Mantén el tronco recto bajo la barra y la cadera mirando al frente.', 'Baja en vertical siguiendo la guía de la máquina y sube con la pierna delantera.', 'Evita acortar tanto la zancada que el talón delantero se levante.', 'Coloca los topes de seguridad a una altura justo por debajo de tu bajada.']::text[], '{}'::text[], true),
  ('smith-machine-squat', 'Smith Machine Squat', 'Sentadilla en máquina Smith', 'Legs', 'Quads', array['Quads', 'Glutes']::text[], array['Adductors']::text[], 'smith-machine', 'squat', 'compound', 'bilateral', array['Colócate bajo la barra con los pies ligeramente por delante de la línea de la barra.', 'Mantén la espalda apoyada en la trayectoria fija y las rodillas alineadas con los pies.', 'Baja controlado hasta la profundidad que domines y sube sin bloquear las rodillas de golpe.', 'Evita poner los pies justo debajo de la barra, que carga demasiado las rodillas.', 'Ajusta los topes de seguridad de la Smith y gira la barra para engancharla al terminar.']::text[], '{}'::text[], true),
  ('standing-calf-raises-toes-neutral', 'Machine Standing Calf Raise', 'Elevación de talones de pie en máquina', 'Legs', 'Calves', array['Calves']::text[], '{}'::text[], 'machine', 'isolation', 'isolation', 'bilateral', array['Coloca los hombros bajo las almohadillas y la parte delantera de los pies en el borde del escalón.', 'Mantén las rodillas extendidas sin bloquear y el cuerpo erguido.', 'Baja los talones hasta el estiramiento, pausa y sube hasta la punta de los pies.', 'Evita rebotar abajo para usar el rebote elástico en lugar del músculo.', 'Apoya bien la planta en el escalón para que el pie no se resbale.']::text[], '{}'::text[], true),
  ('standing-db-lateral-raises', 'Dumbbell Lateral Raise (Standing)', 'Elevaciones laterales con mancuernas (de pie)', 'Shoulders', 'Side Delts', array['Side Delts']::text[], '{}'::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Ponte de pie con los pies a la anchura de la cadera y las mancuernas a los lados.', 'Inclina el torso ligeramente adelante y mantén los codos un poco flexionados.', 'Eleva las mancuernas hacia los lados hasta la altura de los hombros y baja en 2-3 segundos.', 'Evita balancear el cuerpo para lanzar las mancuernas hacia arriba.', 'No subas las manos por encima de los hombros si notas pinzamiento o molestia.']::text[], '{}'::text[], true),
  ('standing-db-offset-grip-curls', 'Dumbbell Curl (Standing, Offset Grip)', 'Curl con mancuernas (de pie, agarre descentrado)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Sujeta cada mancuerna con el meñique pegado al disco interior, dejando más peso hacia el pulgar.', 'Mantén los codos fijos junto al torso y las muñecas neutras, sin doblarlas hacia atrás.', 'Sube girando la palma hacia arriba hasta el final y baja lento resistiendo la rotación.', 'Evita soltar la supinación arriba; el agarre descentrado busca justo esa torsión extra.', 'Elige un peso menor que en el curl normal: el agarre descentrado exige más a la muñeca.']::text[], '{}'::text[], true),
  ('standing-dumbbell-curl', 'Dumbbell Curl (Standing)', 'Curl con mancuernas (de pie)', 'Arms', 'Biceps', array['Biceps']::text[], array['Forearms']::text[], 'dumbbell', 'isolation', 'isolation', 'bilateral', array['Ponte de pie con los pies a la anchura de la cadera y las mancuernas a los lados, palmas al frente.', 'Mantén los codos pegados al costado y el abdomen firme sin inclinarte hacia atrás.', 'Sube las mancuernas hasta la altura del hombro y bájalas en 2-3 segundos hasta extender.', 'Evita balancear el cuerpo o adelantar los codos para ayudarte con el impulso.', 'Si necesitas balancearte para subir, baja el peso y conserva la técnica limpia.']::text[], '{}'::text[], true),
  ('unilateral-supp-rows-reverse-grip', 'Machine Chest-Supported Row (Underhand Grip, Single-Arm)', 'Remo con apoyo de pecho en máquina (agarre supino, a una mano)', 'Back', 'Lats', array['Lats']::text[], array['Upper Back', 'Biceps']::text[], 'machine', 'pull horizontal', 'compound', 'unilateral', array['Apoya el pecho en el cojín y agarra una sola asa con la palma hacia arriba y el brazo estirado.', 'Mantén el pecho fijo y los hombros paralelos al cojín, sin girar el torso.', 'Lleva el codo atrás pegado al costado hacia la cadera y vuelve despacio hasta estirar el dorsal.', 'Evita empujar con la mano libre contra la máquina para ayudarte en el tirón.', 'Trabaja ambos lados con la misma carga y repeticiones para mantener el equilibrio.']::text[], '{}'::text[], true),
  ('v-bb-cable-tricep-extensions', 'Cable Triceps Pushdown (V-Bar)', 'Extensión de tríceps en polea (barra V)', 'Arms', 'Triceps', array['Triceps']::text[], '{}'::text[], 'cable', 'isolation', 'isolation', 'bilateral', array['Coloca la polea alta, sujeta la barra V y deja los codos flexionados junto al torso.', 'Mantén las muñecas rectas y el tronco firme con una ligera inclinación al frente.', 'Extiende los codos hasta bloquear sin golpe y sube hasta que los antebrazos pasen la horizontal.', 'Evita inclinarte sobre la barra para empujar con el peso del cuerpo.', 'Coloca los pies firmes y separados para no perder el equilibrio con cargas altas.']::text[], '{}'::text[], true),
  ('v-up', 'V-Up', 'Abdominales en V', 'Core', 'Abs', array['Abs']::text[], array['Hip Flexors']::text[], 'bodyweight', 'core', 'isolation', 'bilateral', array['Túmbate boca arriba con piernas rectas y brazos extendidos por encima de la cabeza.', 'Mantén las piernas juntas y los brazos alineados con las orejas al subir.', 'Eleva tronco y piernas a la vez hasta tocar los pies y baja despacio sin desplomarte.', 'Evita tirar del cuello o doblar las rodillas para llegar arriba.', 'Mantén la zona lumbar controlada al bajar; si se arquea, reduce el recorrido.']::text[], '{}'::text[], true),
  ('weighted-45-back-extensions', 'Back Extension (45°)', 'Hiperextensión (45°)', 'Glutes', 'Lower Back', array['Lower Back', 'Glutes']::text[], array['Hamstrings']::text[], 'bodyweight', 'hinge', 'compound', 'bilateral', array['Ajusta la almohadilla a la altura de la cadera y fija los talones bajo los rodillos.', 'Mantén la columna neutra y los brazos cruzados o sujetando el lastre contra el pecho.', 'Baja flexionando la cadera hasta notar estiramiento y sube hasta alinear tronco y piernas.', 'Evita pasar de la línea recta arqueando fuerte la zona lumbar arriba.', 'Añade lastre solo cuando completes las repeticiones con técnica limpia.']::text[], '{}'::text[], true),
  ('wide-grip-cable-chest-pulls', 'Cable Pull to Chest (Wide Grip)', 'Jalón en polea al pecho (agarre ancho)', 'Back', 'Upper Back', array['Upper Back']::text[], array['Rear Delts', 'Lats', 'Biceps']::text[], 'cable', 'pull horizontal', 'compound', 'bilateral', array['Colócate frente a la polea con una barra larga a la altura del pecho y agárrala en prono, ancho.', 'Mantén el torso erguido y el pecho alto, con los codos a la altura de los hombros o algo por debajo.', 'Tira la barra hacia el pecho abriendo los codos y juntando las escápulas; vuelve hasta estirar los brazos.', 'Evita echar el cuerpo hacia atrás para acercar la barra; el torso no debe moverse.', 'Ajusta la altura de la polea y el peso antes de empezar para tirar sin tensión en el cuello.']::text[], '{}'::text[], true),
  ('wide-grip-cable-row', 'Cable Seated Row (Wide Grip)', 'Remo sentado en polea (agarre ancho)', 'Back', 'Upper Back', array['Upper Back']::text[], array['Rear Delts', 'Lats', 'Biceps']::text[], 'cable', 'pull horizontal', 'compound', 'bilateral', array['Engancha una barra larga, agárrala en prono más ancho que los hombros y siéntate con la espalda erguida.', 'Mantén los codos abiertos a unos 60-70° del torso y el pecho alto.', 'Tira la barra hacia la parte baja del pecho apretando la zona media de la espalda y vuelve lento.', 'Evita encoger los hombros al final del tirón; termina el movimiento con las escápulas, no con el cuello.', 'Elige un peso que puedas frenar en la vuelta sin que te arrastre hacia delante.']::text[], '{}'::text[], true),
  ('wide-grip-chest-press', 'Machine Chest Press (Wide Grip)', 'Press de pecho en máquina (agarre ancho)', 'Chest', 'Chest', array['Chest']::text[], array['Front Delts', 'Triceps']::text[], 'machine', 'push horizontal', 'compound', 'bilateral', array['Regula el asiento para que los agarres anchos queden a la altura del pecho medio.', 'Apoya bien la espalda y mantén el pecho alto durante todo el movimiento.', 'Empuja hasta casi extender los brazos y regresa lento hasta que las manos queden a la altura del pecho.', 'Evita que la pila de placas choque entre repeticiones; mantén la tensión.', 'Comprueba que el pasador de peso está bien insertado antes de empezar la serie.']::text[], '{}'::text[], true),
  ('wide-grip-shoulder-press-machine', 'Machine Shoulder Press (Wide Grip)', 'Press de hombros en máquina (agarre ancho)', 'Shoulders', 'Front Delts', array['Front Delts']::text[], array['Side Delts', 'Triceps']::text[], 'machine', 'push vertical', 'compound', 'bilateral', array['Siéntate con los agarres anchos a la altura de las orejas y los pies firmes en el suelo.', 'Mantén la espalda contra el respaldo y las muñecas rectas.', 'Empuja hasta casi extender los brazos y desciende con control hasta la posición inicial.', 'Evita encoger los hombros hacia las orejas al empujar.', 'Fija bien el pasador del peso y el asiento antes de cada serie.']::text[], '{}'::text[], true),
  ('wide-grip-supp-seated-row', 'Machine Chest-Supported Row (Wide Grip)', 'Remo con apoyo de pecho en máquina (agarre ancho)', 'Back', 'Upper Back', array['Upper Back']::text[], array['Rear Delts', 'Lats', 'Biceps']::text[], 'machine', 'pull horizontal', 'compound', 'bilateral', array['Ajusta el asiento y el cojín para que los agarres anchos queden a la altura del pecho con brazos estirados.', 'Mantén el pecho apoyado en el cojín y los codos abiertos hacia los lados.', 'Rema hacia atrás hasta que los codos pasen el torso, aprieta las escápulas y vuelve con control.', 'Evita separar el pecho del cojín al final de cada repetición para ganar recorrido.', 'Revisa el pasador y la altura del asiento antes de cada serie.']::text[], '{}'::text[], true)
on conflict (id) do update set
  name_en = excluded.name_en,
  name_es = excluded.name_es,
  body_region = excluded.body_region,
  primary_muscle = excluded.primary_muscle,
  primary_muscles = excluded.primary_muscles,
  secondary_muscles = excluded.secondary_muscles,
  equipment = excluded.equipment,
  movement_pattern = excluded.movement_pattern,
  mechanic = excluded.mechanic,
  laterality = excluded.laterality,
  posture_tips = excluded.posture_tips,
  aliases = excluded.aliases,
  is_active = excluded.is_active,
  updated_at = now();
